const expected = msg.expected_state || msg.payload?.expected_state;
const labels = {
    lampada_varanda: 'varanda',
    lampadas_garagem: 'garagem',
    refletores_jardim: 'jardim'
};
const states = {
    lampada_varanda: msg.payload?.lampada_varanda,
    lampadas_garagem: msg.payload?.lampadas_garagem,
    refletores_jardim: msg.payload?.refletores_jardim
};
const networkFailureStates = new Set([undefined, null, '', 'unknown', 'unavailable']);
const unavailable = Object.entries(states)
    .filter(([, state]) => networkFailureStates.has(state))
    .map(([entity]) => labels[entity]);

if (flow.get('external_lighting_zigbee_state') === 'offline' || unavailable.length > 0) {
    msg.zigbee_error = true;
    const affected = unavailable.length > 0 ? ` Sem comunicação com: ${unavailable.join(', ')}.` : '';
    msg.notify_text = `Erro na rede Zigbee.${affected} O comando da iluminação externa não será repetido.`;
    return msg;
}

const failed = Object.entries(states)
    .filter(([, state]) => state !== expected)
    .map(([entity, state]) => `${labels[entity]} ${state}`);

if (failed.length === 0) {
    msg.notify_text = msg.notify_success || msg.notify_text;
    return msg;
}

const expectedText = expected === 'on' ? 'ligada' : 'desligada';
msg.notify_text = `Erro ao acionar a iluminação externa. Esperado: ${expectedText}. Estado atual: ${failed.join(', ')}. O comando não será repetido.`;
return msg;

const getState = (value) => {
    if (value === undefined || value === null) return undefined;
    if (typeof value === "string") return value;
    if (typeof value === "object" && value.state !== undefined) return value.state;
    return undefined;
};

// "unknown"/"unavailable" sao glitches momentaneos da integracao moni_mobile
// (falha de parsing no protocolo TCP) e nao devem contar como estado real,
// nem entrar no historico usado para detectar mudanca.
const isUnknown = (state) =>
    state === undefined ||
    state === null ||
    state === "" ||
    state === "unknown" ||
    state === "unavailable";

const data = msg.data?.event ?? msg.data ?? {};

const oldStateRaw =
    getState(data.old_state) ??
    getState(msg.old_state);

const newState =
    getState(data.new_state) ??
    getState(msg.new_state) ??
    getState(msg.payload);

const entityId =
    data.entity_id ??
    msg.topic ??
    "alarm_control_panel.alarme_moni_mobile";

const cacheKey = `last_alarm_state:${entityId}`;

if (!newState) {
    node.status({
        fill: "red",
        shape: "ring",
        text: "sem estado novo"
    });
    return null;
}

if (isUnknown(newState)) {
    node.status({
        fill: "grey",
        shape: "ring",
        text: `ignorado: ${newState}`
    });
    return null;
}

// Se o old_state vindo do evento for "unknown", usa o ultimo estado real
// salvo no flow context em vez de tratar o glitch como estado anterior.
const lastState = !isUnknown(oldStateRaw) ? oldStateRaw : flow.get(cacheKey);

flow.set(cacheKey, newState);

if (lastState === newState) {
    node.status({
        fill: "grey",
        shape: "ring",
        text: `bloqueado: ${lastState} -> ${newState}`
    });
    return null;
}

msg.previous_alarm_state = lastState ?? "desconhecido";
msg.current_alarm_state = newState;
msg.alarm_state_changed = true;

node.status({
    fill: "green",
    shape: "dot",
    text: `${lastState ?? "?"} -> ${newState}`
});

return msg;

const attempt = Number(msg.arm_alarm_retry_count || 0) + 1;
msg.arm_alarm_retry_count = attempt;
const errorMessage = msg.error?.message || msg.error?.source?.name || 'erro desconhecido';

node.status({ fill: "yellow", shape: "dot", text: `tentativa ${attempt}: ${errorMessage}` });
node.warn(`Erro ao armar o alarme (tentativa ${attempt}): ${errorMessage}. Nova tentativa em instantes.`);

// Avisa no primeiro erro e depois a cada 5 tentativas para nao spammar o Alexa
// enquanto o dispositivo moni_mobile estiver offline.
if (attempt === 1 || attempt % 5 === 0) {
    msg.notify_text = attempt === 1
        ? 'Não foi possível armar o alarme: dispositivo offline. Tentando novamente...'
        : `Ainda tentando armar o alarme (tentativa ${attempt}). Dispositivo continua offline.`;
    return [msg, msg];
}
return [msg, null];

const attempt = Number(msg.disarm_alarm_retry_count || 0) + 1;
msg.disarm_alarm_retry_count = attempt;
const errorMessage = msg.error?.message || msg.error?.source?.name || 'erro desconhecido';

node.status({ fill: "yellow", shape: "dot", text: `tentativa ${attempt}: ${errorMessage}` });
node.warn(`Erro ao desarmar o alarme (tentativa ${attempt}): ${errorMessage}. Nova tentativa em instantes.`);

// Avisa no primeiro erro e depois a cada 5 tentativas para nao spammar o Alexa
// enquanto o dispositivo moni_mobile estiver offline.
if (attempt === 1 || attempt % 5 === 0) {
    msg.notify_text = attempt === 1
        ? 'Não foi possível desarmar o alarme: dispositivo offline. Tentando novamente...'
        : `Ainda tentando desarmar o alarme (tentativa ${attempt}). Dispositivo continua offline.`;
    return [msg, msg];
}
return [msg, null];

const desired = flow.get("alarm_desired");
// Aborta a tentativa de armar se o comando mais recente ja foi desarmar,
// evitando que um loop de retry (device offline) re-arme por cima de um
// desarme bem-sucedido feito nesse meio tempo.
if (desired !== "arm") {
    node.status({ fill: "blue", shape: "ring", text: `retry armar cancelado (desejado: ${desired || "?"})` });
    node.warn("Retry de ARMAR cancelado: comando mais recente foi desarmar.");
    return null;
}
return msg;

const desired = flow.get("alarm_desired");
// Espelho de alarm_guard_arm: aborta o retry de desarmar se o comando
// mais recente ja foi armar.
if (desired !== "disarm") {
    node.status({ fill: "blue", shape: "ring", text: `retry desarmar cancelado (desejado: ${desired || "?"})` });
    node.warn("Retry de DESARMAR cancelado: comando mais recente foi armar.");
    return null;
}
return msg;

msg.operation = "start";
msg.attempt = Number(msg.attempt || 1);
msg.start_source = msg.start_source || "temperature_threshold";
msg.trigger_temperature = Number(msg.payload);
return msg;

msg.operation = "startup";
msg.attempt = Number(msg.attempt || 1);
msg.start_source = "startup_reconciliation";
return msg;

const temperature = Number(msg.cpu_temperature);
const owner = msg.cooling_owner;
let pendingSnapshot = null;

if (typeof msg.stored_snapshot === "string" && msg.stored_snapshot.trim()) {
    try {
        const parsed = JSON.parse(msg.stored_snapshot);
        if (parsed && typeof parsed.state === "string") pendingSnapshot = parsed;
    } catch (error) {
        node.warn("Snapshot pendente inválido no startup: " + error.message);
    }
}

if (!Number.isFinite(temperature)) {
    node.warn("Reconciliação ignorada: temperatura da CPU inválida.");
    return null;
}

msg.trigger_temperature = temperature;
if (temperature > 81.9) {
    msg.operation = "start";
    msg.start_source = "startup_reconciliation";
    if (owner === "off" && pendingSnapshot) msg.previous_climate = pendingSnapshot;
    return [msg, null];
}

if (owner === "on" && temperature < 70) {
    msg.operation = "stop";
    msg.stop_source = "startup_reconciliation";
    return [null, msg];
}

if (owner === "off" && temperature < 70 && pendingSnapshot) {
    msg.operation = "rollback";
    msg.stop_source = "startup_incomplete_acquisition";
    msg.previous_climate = pendingSnapshot;
    flow.set("rpi_emergency_cooling_operation", "rollback");
    node.warn("Retomando rollback de uma aquisição interrompida antes do ownership.");
    return [null, null, msg];
}

node.status({ fill: "grey", shape: "ring", text: owner === "on" ? "aguardando faixa segura" : "sem ação" });
return null;

const LOCK_KEY = "rpi_emergency_cooling_operation";
const owner = msg.cooling_owner;

if (owner === "on" && msg.start_source !== "startup_reconciliation") {
    node.status({ fill: "blue", shape: "ring", text: "já controlado pelo fluxo" });
    return null;
}

if (!['on', 'off'].includes(owner)) {
    msg.failure_reason = "helper de ownership em estado " + String(owner || "desconhecido");
    return [null, msg];
}

if (flow.get(LOCK_KEY)) {
    node.status({ fill: "grey", shape: "ring", text: "operação já em andamento" });
    return null;
}

flow.set(LOCK_KEY, "start");
msg.operation = "start";
msg.start_mode = owner === "on" ? "reconcile" : "acquire";
msg.attempt = Number(msg.attempt || 1);
node.status({ fill: "yellow", shape: "dot", text: msg.start_mode === "reconcile" ? "reconciliando" : "assumindo controle" });
return [msg, null];

const state = msg.climate_state;
const entity = msg.climate_entity;

if (!entity || ['unknown', 'unavailable', undefined, null, ''].includes(state)) {
    msg.failure_reason = "climate indisponível (estado " + String(state || "ausente") + ")";
    node.status({ fill: "red", shape: "ring", text: "climate indisponível" });
    return [null, null, msg];
}

if (msg.start_mode === "acquire" && !msg.previous_climate && typeof msg.stored_snapshot === "string" && msg.stored_snapshot.trim()) {
    try {
        const parsed = JSON.parse(msg.stored_snapshot);
        if (parsed && typeof parsed.state === "string") msg.previous_climate = parsed;
    } catch (error) {
        node.warn("Snapshot persistente inválido; capturando estado atual: " + error.message);
    }
}

if (msg.start_mode === "acquire" && !msg.previous_climate) {
    const temperature = Number(entity.attributes?.temperature);
    const fanMode = entity.attributes?.fan_mode;
    msg.previous_climate = {
        state,
        temperature: Number.isFinite(temperature) ? temperature : null,
        fan_mode: typeof fanMode === "string" && fanMode ? fanMode : null,
        captured_at: new Date().toISOString()
    };
}

return msg.start_mode === "acquire" ? [msg, null, null] : [null, msg, null];

msg.control_started = true;
if (msg.start_mode === "acquire") msg.snapshot_persisted = true;
return msg;

const entity = msg.controlled_climate_entity;
const state = msg.controlled_climate_state;
const temperature = Number(entity?.attributes?.temperature);
const fanMode = entity?.attributes?.fan_mode;
const valid = entity && state === "cool" && Number.isFinite(temperature) && Math.abs(temperature - 16) < 0.01 && fanMode === "high";

if (!valid) {
    msg.failure_reason = "climate não confirmou cool/16 °C/high (estado=" + String(state) + ", temperatura=" + String(entity?.attributes?.temperature) + ", fan=" + String(fanMode) + ")";
    node.status({ fill: "red", shape: "ring", text: "estado de emergência não confirmado" });
    return [null, msg];
}

return [msg, null];

if (msg.start_mode === "reconcile") {
    flow.set("rpi_emergency_cooling_operation", null);
    node.status({ fill: "green", shape: "dot", text: "reconciliado sem duplicar alerta" });
