return [msg, null, null];

flow.set("rpi_emergency_cooling_operation", null);
msg.started_at = new Date().toISOString();
node.status({ fill: "green", shape: "dot", text: "resfriamento controlado" });
return [msg, msg, msg];

const LOCK_KEY = "rpi_emergency_cooling_operation";
flow.set(LOCK_KEY, null);
const operation = msg.operation || "start";
const attempt = Math.max(1, Number(msg.attempt || 1));
