const clearSnapshot = operation === "start" && msg.start_mode === "acquire" && msg.snapshot_persisted && !rollback;
if (rollback) msg.operation = "rollback";
if (rollback) flow.set(LOCK_KEY, "rollback");
return [null, null, rollback ? msg : null, clearSnapshot ? msg : null, msg];

flow.set("rpi_emergency_cooling_operation", null);
node.status({ fill: "grey", shape: "ring", text: "retry cancelado: CPU normalizou" });
const rollback = msg.start_mode === "acquire" && msg.control_started && msg.previous_climate;
if (rollback) {
    msg.operation = "rollback";
    flow.set("rpi_emergency_cooling_operation", "rollback");
}
return [rollback ? msg : null, !rollback && msg.snapshot_persisted ? msg : null];

msg.operation = "stop";
msg.attempt = Number(msg.attempt || 1);
msg.stop_source = msg.stop_source || "temperature_window";
msg.trigger_temperature = Number(msg.trigger_temperature ?? msg.payload);
return msg;

const LOCK_KEY = "rpi_emergency_cooling_operation";
if (flow.get(LOCK_KEY)) {
    node.status({ fill: "grey", shape: "ring", text: "operação já em andamento" });
    return null;
}
flow.set(LOCK_KEY, "stop");
msg.operation = "stop";
msg.attempt = Number(msg.attempt || 1);
return msg;

if (!msg.climate_entity || ['unknown', 'unavailable', undefined, null, ''].includes(msg.climate_state)) {
    msg.failure_reason = "climate indisponível durante " + (msg.operation === "rollback" ? "rollback" : "encerramento");
    return [null, null, msg];
}

let restore = msg.previous_climate;
if (!restore && typeof msg.stored_snapshot === "string" && msg.stored_snapshot.trim()) {
    try { restore = JSON.parse(msg.stored_snapshot); } catch (error) { msg.snapshot_error = error.message; }
}

if (!restore || typeof restore.state !== "string" || ['unknown', 'unavailable', ''].includes(restore.state)) {
    if (msg.operation === "rollback") {
        msg.failure_reason = "snapshot inválido para rollback";
        return [null, null, msg];
    }
    restore = { state: "off", temperature: null, fan_mode: null };
    msg.restore_fallback = true;
