msg.restore = restore;
return restore.state === "off" ? [msg, null, null] : [null, msg, null];

const fanMode = msg.restore?.fan_mode;
return typeof fanMode === "string" && fanMode && !['unknown', 'unavailable'].includes(fanMode)
    ? [msg, null]
    : [null, msg];

const entity = msg.restored_climate_entity;
const state = msg.restored_climate_state;
const restore = msg.restore;

if (!entity || ['unknown', 'unavailable', undefined, null, ''].includes(state) || !restore) {
    msg.failure_reason = "climate indisponível ao confirmar restauração";
    return [null, msg];
}

let valid = state === restore.state;
const expectedTemperature = Number(restore.temperature);
const actualTemperature = Number(entity.attributes?.temperature);
if (restore.state !== "off" && Number.isFinite(expectedTemperature)) {
    valid = valid && Number.isFinite(actualTemperature) && Math.abs(actualTemperature - expectedTemperature) < 0.01;
}

const expectedFan = restore.fan_mode;
if (restore.state !== "off" && typeof expectedFan === "string" && expectedFan && !['unknown', 'unavailable'].includes(expectedFan)) {
    valid = valid && entity.attributes?.fan_mode === expectedFan;
}

if (!valid) {
    msg.failure_reason = "climate não confirmou o estado anterior (modo=" + String(state) + ", temperatura=" + String(entity.attributes?.temperature) + ", fan=" + String(entity.attributes?.fan_mode) + ")";
    node.status({ fill: "red", shape: "ring", text: "restauração não confirmada" });
    return [null, msg];
}

return [msg, null];

if (msg.operation === "rollback") {
    node.status({ fill: "yellow", shape: "ring", text: "rollback concluído; liberando ownership" });
    return [null, msg];
}
return [msg, null];

flow.set("rpi_emergency_cooling_operation", null);
node.status({ fill: "yellow", shape: "dot", text: "rollback concluído" });
return msg;

flow.set("rpi_emergency_cooling_operation", null);
msg.normalized_at = new Date().toISOString();
node.status({ fill: "green", shape: "dot", text: msg.restore?.state === "off" ? "desligado" : "estado anterior restaurado" });
return [msg, msg, msg, msg];

flow.set("rpi_emergency_cooling_operation", null);
const attempt = Math.max(1, Number(msg.attempt || 1));
const reason = msg.failure_reason || msg.error?.message || "falha desconhecida";
msg.failure_reason = reason;
msg.failure_operation = msg.operation || "stop";
node.warn("Encerramento do resfriamento: " + reason + " (tentativa " + attempt + "/3)");

if (msg.operation === "stop" && attempt < 3) {
    msg.attempt = attempt + 1;
    delete msg.error;
    return [msg, null];
}

msg.attempt = attempt;
return [null, msg];

flow.set("rpi_emergency_cooling_operation", null);
node.status({ fill: "grey", shape: "ring", text: "saída cancelada: CPU voltou a subir" });
return null;

const config = {
    version: 1,
    thresholds: { warning: 70, high: 80, critical: 90 },
    hysteresisPercentagePoints: 3,
    notificationCooldownMs: 12 * 60 * 60 * 1000,
