    }
  } else if (state.incident_open) {
    state.phase = "offline";
  } else if (stableForMs >= 30_000) {
    state.phase = "offline";
    state.incident_open = true;
    state.outage_started_at = new Date(Number(observation.changed_at || now)).toISOString();
    state.last_outage_at = state.outage_started_at;
    downNotification = {
      notification: {
        id: "zigbee_network_failure",
        title: "Falha na rede Zigbee",
        message: `A rede Zigbee está indisponível. O Zigbee2MQTT perdeu a conexão com a antena/coordenador ou parou de funcionar. Detectado em ${new Date(now).toLocaleString("pt-BR")}.`,
      },
    };
  } else {
    state.phase = "checking";
  }

  state.raw_state = rawState;
  state.last_checked_at = nowIso;
  state.stable_for_s = Math.floor(stableForMs / 1000);
  flow.set(KEY, state, "persistent");
  const attributes = {
    state: state.phase,
    raw_state: rawState,
    stable_for_s: state.stable_for_s,
    checked_at: nowIso,
    last_outage: state.last_outage_at,
    last_recovery: state.last_recovery_at,
    last_outage_duration_s: state.last_outage_duration_s,
    failure_confirmation_s: 30,
    recovery_confirmation_s: 60,
  };
  const publications = [
    { topic: "nodered/infrastructure/zigbee/connection", payload: state.phase === "online" ? "ON" : "OFF" },
    { topic: "nodered/infrastructure/zigbee/attributes", payload: JSON.stringify(attributes) },
    { topic: "nodered/infrastructure/zigbee/state", payload: state.phase },
  ];
  node.status({
    fill: state.phase === "online" ? "green" : state.phase === "offline" ? "red" : "yellow",
    shape: state.phase === "online" ? "dot" : "ring",
    text: `${state.phase}: ${rawState}`,
  });
  return [downNotification, recoveryNotification, publications];

const device = {
    identifiers: ["node_red_infrastructure_monitoring"],
    name: "Monitoramento de infraestrutura",
    manufacturer: "Node-RED",
    model: "Flows de disponibilidade",
  };
  const availability = {
    availability_topic: "nodered/status",
    payload_available: "online",
    payload_not_available: "offline",
  };
  return [[
    {
      topic: "homeassistant/binary_sensor/zigbee_network/config",
      payload: JSON.stringify({
        name: "Rede Zigbee",
        object_id: "zigbee_network",
        default_entity_id: "binary_sensor.zigbee_network",
        unique_id: "node_red_zigbee_network",
        device_class: "connectivity",
        state_topic: "nodered/infrastructure/zigbee/connection",
        json_attributes_topic: "nodered/infrastructure/zigbee/attributes",
        payload_on: "ON",
        payload_off: "OFF",
        ...availability,
        device,
      }),
    },
    {
      topic: "homeassistant/sensor/zigbee_network_state/config",
      payload: JSON.stringify({
        name: "Estado da rede Zigbee",
        object_id: "zigbee_network_state",
        default_entity_id: "sensor.zigbee_network_state",
        unique_id: "node_red_zigbee_network_state",
        icon: "mdi:zigbee",
        entity_category: "diagnostic",
        state_topic: "nodered/infrastructure/zigbee/state",
        json_attributes_topic: "nodered/infrastructure/zigbee/attributes",
        ...availability,
        device,
      }),
    },
  ]];

const HOME_LAT = Number(env.get("HOME_LAT"));
const HOME_LON = Number(env.get("HOME_LON"));
const GATE_LAT = Number(env.get("GATE_LAT"));
const GATE_LON = Number(env.get("GATE_LON"));
const HOME_KNOWN = Number.isFinite(HOME_LAT) && Number.isFinite(HOME_LON);
const GATE_KNOWN = Number.isFinite(GATE_LAT) && Number.isFinite(GATE_LON);

const ARM_DISTANCE_M = 100;
const ARRIVAL_DISTANCE_M = 300;
const MAX_GPS_ACCURACY_M = 100;
const APPROACH_ZONE = "chegando";
const PRIMARY_HOME_GRACE_MS = 10 * 60 * 1000;
const LOCATION_FRESH_MS = 15 * 60 * 1000;

const RECOVERY_KEY = "security_people_recovery_v1";
const PERSISTENT = "persistent";
const DEDUPE_TTL_MS = 10 * 60 * 1000;
const FUTURE_TOLERANCE_MS = 60 * 1000;
const ARMED_KEY = "people_arrival_armed";
const VALERIA_NOTIFY_KEY = "valeria_approaching_gabriel_notified";
const VALERIA_AWAY_CYCLE_KEY = "valeria_approaching_confirmed_away_cycle";

const TEST_MODE =
    msg._location_test === true ||
    msg.payload?.test_mode === true;

const SHARED_TEST_KEY = "security_location_test_state_v1";

function testBaseline(now = Date.now()) {
    return {
        version: 1,
        gabriel: "home",
        valeria: "home",
        creta: "home",
        creta_engine: "off",
        creta_lock: "locked",
        observed_at: now,
        transitions: {}
    };
}

function clearPeopleTestState() {
    [
        "security_people_recovery_v1__test",
        "people_arrival_armed__test",
        "valeria_approaching_gabriel_notified__test",
        "valeria_approaching_confirmed_away_cycle__test",
        "people_context_v1__test",
        "security_people_ready_logged__test",
        "security_people_test_clock"
    ].forEach((key) => flow.set(key, undefined));
}

/*
 * O snapshot continua vindo do ciclo real do contexto_chegadas.
 * Em TEST_MODE, somente os valores lidos são substituídos pelo
 * estado sintético COMPARTILHADO entre Pessoas e Creta.
 */
if (
    TEST_MODE &&
    msg.payload?.event === "context_snapshot"
) {
    if (msg._location_test_reset === true) {
        clearPeopleTestState();
    }

    let shared = global.get(SHARED_TEST_KEY);
    if (!shared || shared.version !== 1) {
        shared = testBaseline();
        global.set(SHARED_TEST_KEY, shared);
    }

    const refreshCycleId = msg.payload?.refresh_cycle_id;
    const testAt = Math.max(
        Date.now(),
        Number(shared.observed_at || 0)
    );
    const now = new Date(testAt).toISOString();

    function testTracker(entityId, state) {
        return {
            entity_id: entityId,
            state,
            attributes: { gps_accuracy: 20 },
            last_changed: now,
            last_updated: now
        };
    }

    const transition = shared.transitions?.people;
    const activeTransition =
        transition?.domain === "people" &&
        transition?.test_case === msg._location_test_case &&
        msg._location_test_reset !== true;

    const source = activeTransition
        ? transition.source
        : "refresh";

    msg.payload = {
        event: activeTransition
            ? "location_update"
            : "context_snapshot",
        source,
        refresh_cycle_id: refreshCycleId,
        trigger_entity: activeTransition
            ? (
                source === "gabriel"
                    ? "device_tracker.iphone_de_gabriel_furlan"
                    : "device_tracker.iphone_de_valeria"
            )
            : undefined,
        trigger_state: activeTransition
            ? transition.state
            : undefined,
        trigger_prev_state: activeTransition
            ? transition.prev
            : undefined,
        gabriel: testTracker(
            "device_tracker.iphone_de_gabriel_furlan",
            shared.gabriel
        ),
        gabriel_icloud: testTracker(
            "device_tracker.iphonegabrielfurlan",
            shared.gabriel
        ),
        valeria: testTracker(
            "device_tracker.iphone_de_valeria",
            shared.valeria
        ),
        valeria_icloud: testTracker(
            "device_tracker.iphone_de_valeria_2",
            shared.valeria
        )
    };
}

/*
 * Durante um teste, somente o estado interno deste normalizador
 * é isolado. As três saídas continuam sendo as saídas normais
 * do fluxo, permitindo ensaiar toda a cadeia posterior.
 */
function contextKey(base) {
    return TEST_MODE ? `${base}__test` : base;
}

function ctxGet(base, store) {
    const key = contextKey(base);
    return TEST_MODE || !store
        ? flow.get(key)
        : flow.get(key, store);
}

function ctxSet(base, value, store) {
    const key = contextKey(base);

    return TEST_MODE || !store
        ? flow.set(key, value)
        : flow.set(key, value, store);
}

/*
 * Impede que unknown/unavailable/null sejam interpretados
 * como origem válida de uma transição real.
 */
function validZoneState(value) {
    return (
        typeof value === "string" &&
        !["", "unknown", "unavailable"].includes(value)
    );
}

function distanceMeters(lat1, lon1, lat2, lon2) {
    const toRad = (value) => value * Math.PI / 180;

    const dLat = toRad(lat2 - lat1);
    const dLon = toRad(lon2 - lon1);

    const a =
        Math.sin(dLat / 2) ** 2 +
        Math.cos(toRad(lat1)) *
        Math.cos(toRad(lat2)) *
        Math.sin(dLon / 2) ** 2;

    return (
        6371000 *
        2 *
        Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))
    );
}

function reliableCoords(entity) {
    const attrs = entity?.attributes ?? {};

    const lat = Number(attrs.latitude);
    const lon = Number(attrs.longitude);
    const accuracy = Number(attrs.gps_accuracy);

    const hasCoords =
        Number.isFinite(lat) &&
        Number.isFinite(lon);

    const hasAccuracy = Number.isFinite(accuracy);

    return hasCoords &&
        (!hasAccuracy || accuracy <= MAX_GPS_ACCURACY_M)
        ? { lat, lon }
        : null;
}

function primaryHome(entity) {
    const coords = reliableCoords(entity);

    if (HOME_KNOWN && coords) {
        return (
            distanceMeters(
                HOME_LAT,
                HOME_LON,
                coords.lat,
                coords.lon
            ) <= ARM_DISTANCE_M
        );
    }

    const accuracy = Number(
        entity?.attributes?.gps_accuracy
    );

    if (
        Number.isFinite(accuracy) &&
        accuracy > MAX_GPS_ACCURACY_M
    ) {
        return false;
    }

    return entity?.state === "home";
}

function homeForMs(entity) {
    const changedAt = Date.parse(
        entity?.last_changed ?? ""
    );

    return Number.isFinite(changedAt)
        ? Date.now() - changedAt
        : null;
}

function observedAt(entity) {
    const value = Date.parse(
        entity?.last_updated ??
        entity?.last_changed ??
        ""
    );

    return Number.isFinite(value)
        ? value
        : null;
}

function freshTracker(entity) {
    const value = observedAt(entity);

    return (
        value !== null &&
        value <= Date.now() + FUTURE_TOLERANCE_MS &&
        Date.now() - value <= LOCATION_FRESH_MS
    );
}

function mergeTrackers(primary, fallback) {
    const primaryFresh = freshTracker(primary);
    const fallbackFresh = freshTracker(fallback);

    if (primaryFresh !== fallbackFresh) {
        return primaryFresh
            ? primary
            : fallback;
    }

    const primaryCoords = reliableCoords(primary);
    const fallbackCoords = reliableCoords(fallback);

    if (
        HOME_KNOWN &&
        primaryCoords &&
        fallbackCoords
    ) {
        const primaryDistance = distanceMeters(
            HOME_LAT,
            HOME_LON,
            primaryCoords.lat,
            primaryCoords.lon
        );

        const fallbackDistance = distanceMeters(
            HOME_LAT,
            HOME_LON,
            fallbackCoords.lat,
            fallbackCoords.lon
        );

        return fallbackDistance > primaryDistance
            ? fallback
            : primary;
    }

    if (primaryCoords) return primary;
    if (fallbackCoords) return fallback;

    if (
        primary?.state === "home" &&
        fallback?.state === "not_home"
    ) {
        return fallback;
    }

    return primary;
}

function position(primary, fallback) {
    const selected = mergeTrackers(
        primary,
        fallback
    );

    const attrs = selected?.attributes ?? {};
    const coords = reliableCoords(selected);

    const accuracy = Number(
        attrs.gps_accuracy
    );

    const state = selected?.state;

    const validState =
        typeof state === "string" &&
        ![
            "unknown",
            "unavailable",
            ""
        ].includes(state);

    const updatedAt =
        observedAt(selected);

    const stale =
        updatedAt === null ||
        Date.now() - updatedAt > LOCATION_FRESH_MS ||
        updatedAt > Date.now() + FUTURE_TOLERANCE_MS;

    return {
        entity_id: selected?.entity_id,
        state,

        latitude:
            coords?.lat ?? null,

        longitude:
            coords?.lon ?? null,

        gps_accuracy:
            Number.isFinite(accuracy)
                ? accuracy
                : null,

        location_reliable:
            Boolean(coords),

        state_valid:
            validState &&
            !stale &&
            (
                Boolean(coords) ||
                [
                    "home",
                    "not_home",
                    APPROACH_ZONE
                ].includes(state)
            ),

        updated_at: updatedAt,
        stale,
        ready:
            validState &&
            !stale,

        distance_m:
            HOME_KNOWN && coords
                ? Math.round(
                    distanceMeters(
                        HOME_LAT,
                        HOME_LON,
                        coords.lat,
                        coords.lon
                    )
                )
                : null,

        gate_distance_m:
            GATE_KNOWN && coords
                ? Math.round(
                    distanceMeters(
                        GATE_LAT,
                        GATE_LON,
                        coords.lat,
                        coords.lon
                    )
                )
                : null,

        current_home:
            validState && !stale
                ? primaryHome(selected)
                : null,

        primary_home:
            primaryHome(primary),

        any_tracker_home:
            primaryHome(primary) ||
            primaryHome(fallback),

        primary_home_for_ms:
            homeForMs(primary)
    };
}

function isAway(item) {
    if (item?.ready !== true) {
        return false;
    }

    if (item?.distance_m !== null) {
        return (
            item.distance_m >
            ARM_DISTANCE_M
        );
    }

    return item?.state === "not_home";
}

function isArmingHome(item) {
    if (item?.ready !== true) {
        return false;
    }

    if (item?.distance_m !== null) {
        return (
            item.distance_m <=
            ARM_DISTANCE_M
        );
    }

    if (
        item?.gps_accuracy !== null &&
        item.gps_accuracy >
        MAX_GPS_ACCURACY_M
    ) {
        return false;
    }

    return item?.state === "home";
}

function isArrivalHome(item) {
    if (item?.ready !== true) {
        return false;
    }

    if (
        item?.gate_distance_m !== null &&
        item.gate_distance_m <=
        ARRIVAL_DISTANCE_M
    ) {
        return true;
    }

    if (item?.distance_m !== null) {
        return (
            item.distance_m <=
            ARRIVAL_DISTANCE_M
        );
    }

    if (
        item?.gps_accuracy !== null &&
        item.gps_accuracy >
        MAX_GPS_ACCURACY_M
    ) {
        return false;
    }

    return item?.state === "home";
}

function validObject(value) {
    return (
        value &&
        typeof value === "object" &&
        !Array.isArray(value)
    );
}


/* ================================
 * NORMALIZAÇÃO
 * ================================ */

const gabriel = position(
    msg.payload?.gabriel,
    msg.payload?.gabriel_icloud
);

const valeria = position(
    msg.payload?.valeria,
    msg.payload?.valeria_icloud
);

const people = {
    gabriel,
    valeria
};

const source =
    msg.payload?.source;

const sourcePosition =
    people[source];

const triggerState =
    msg.payload?.trigger_state;

const triggerPrevState =
    msg.payload?.trigger_prev_state;

const triggerPrevValid =
    validZoneState(
        triggerPrevState
    );

const isLocationEvent =
    msg.payload?.event ===
    "location_update";


/* ================================
 * RECOVERY
 * ================================ */

let recovery =
    ctxGet(
        RECOVERY_KEY,
        PERSISTENT
    );

if (
    !validObject(recovery) ||
    recovery.version !== 1
) {
    if (recovery !== undefined) {
        node.warn(
            "localizacao_pessoas: recovery persistido invalido; descartado"
        );
    }

    recovery = {
        version: 1
    };
}

if (
    !validObject(
        recovery.recent_arrivals
    )
) {
    recovery.recent_arrivals = {};
}

for (
    const [
        itemKey,
        timestamp
    ]
    of Object.entries(
        recovery.recent_arrivals
    )
) {
    if (
        !Number.isFinite(timestamp) ||
        timestamp >
        Date.now() +
        FUTURE_TOLERANCE_MS ||
        Date.now() -
        timestamp >
        DEDUPE_TTL_MS
    ) {
        delete recovery
            .recent_arrivals[
            itemKey
        ];
    }
}


/* ================================
 * CONTEXTO VALÉRIA
 * ================================ */

if (
    ctxGet(
        VALERIA_NOTIFY_KEY
    ) === undefined &&
    typeof recovery
        .valeria_notified ===
    "boolean"
) {
    ctxSet(
        VALERIA_NOTIFY_KEY,
        recovery
            .valeria_notified
    );
}

if (
    ctxGet(
        VALERIA_AWAY_CYCLE_KEY
    ) === undefined &&
    typeof recovery
        .valeria_away_cycle ===
    "boolean"
) {
    ctxSet(
        VALERIA_AWAY_CYCLE_KEY,
        recovery
            .valeria_away_cycle
    );
}


/* ================================
 * ARMAMENTO
 * ================================ */

let armed =
    ctxGet(
        ARMED_KEY
    );

if (!validObject(armed)) {
    armed =
        validObject(
            recovery
                .arrival_armed
        )
            ? recovery
                .arrival_armed
            : {};
}

armed = {
    gabriel:
        armed.gabriel === true,

    valeria:
        armed.valeria === true
};

for (
    const [
        name,
        item
    ]
    of Object.entries(
        people
    )
) {
    if (isAway(item)) {
        armed[name] = true;
    }
}


/* ================================
 * NOTIFICAÇÃO VALÉRIA
 * ================================ */

let notification = null;

if (
    isLocationEvent &&
    source === "valeria"
) {
    if (
        triggerPrevValid &&
        triggerState ===
        "not_home" &&
        (
            triggerPrevState ===
            APPROACH_ZONE ||
            triggerPrevState ===
            "home"
        )
    ) {
        ctxSet(
            VALERIA_AWAY_CYCLE_KEY,
            true
        );
    }

    const confirmedAwayCycle =
        ctxGet(
            VALERIA_AWAY_CYCLE_KEY
        ) === true;

    const approachForNotification =
        valeria.ready === true &&
        triggerPrevValid &&
        triggerState ===
        APPROACH_ZONE &&
        triggerPrevState !==
        APPROACH_ZONE &&
        triggerPrevState !==
        "home" &&
        (
            valeria.any_tracker_home !==
            true ||
            confirmedAwayCycle
        );

    if (
        triggerState ===
        "not_home" ||
        (
            valeria.distance_m !==
            null &&
            valeria.distance_m >
            1000
        )
    ) {
        ctxSet(
            VALERIA_NOTIFY_KEY,
            false
        );
    }

    if (
        triggerState ===
        "home"
    ) {
        ctxSet(
            VALERIA_AWAY_CYCLE_KEY,
            false
        );
    }

    const eventAt =
        valeria.updated_at ??
        Date.now();

    const notificationKey =
        [
            "valeria",
            triggerState ?? "?",
            eventAt
        ].join(":");

    const previousAt =
        Number(
            recovery
                .last_valeria_notification_at ??
            0
        );

    const notificationDuplicate =
        recovery
            .last_valeria_notification_key ===
        notificationKey &&
        previousAt <=
        Date.now() +
        FUTURE_TOLERANCE_MS &&
        Date.now() -
        previousAt <
        DEDUPE_TTL_MS;

    if (
        approachForNotification &&
        ctxGet(
            VALERIA_NOTIFY_KEY
        ) !== true &&
        !notificationDuplicate
    ) {
        ctxSet(
            VALERIA_NOTIFY_KEY,
            true
        );

        recovery
            .last_valeria_notification_key =
            notificationKey;

        recovery
            .last_valeria_notification_at =
            Date.now();

        notification = {
            _location_test:
                TEST_MODE,

            _location_test_case:
                TEST_MODE
                    ? (msg._location_test_case ?? null)
                    : undefined,

            payload: {
                contract:
                    "security.person-arrival-notification.v1",

                kind:
                    "valeria_approach_notification",

                notification_key:
                    notificationKey,

                event_at:
                    eventAt,

                valeria_distance_m:
                    valeria.distance_m
            }
        };
    }
}


/* ================================
 * DETECÇÃO DE CHEGADA
 * ================================ */

let arrival = null;

if (
    isLocationEvent &&
    sourcePosition?.ready ===
    true &&
    triggerPrevValid
) {
    const approachEntry =
        triggerState ===
        APPROACH_ZONE &&
        triggerPrevState !==
        APPROACH_ZONE &&
        triggerPrevState !==
        "home" &&
        sourcePosition
            .any_tracker_home !==
        true;

    const leavingHome =
        triggerPrevState ===
        "home";

    const staleCatchUp =
        !approachEntry &&
        sourcePosition
            .primary_home ===
        true &&
        typeof sourcePosition
            .primary_home_for_ms ===
        "number" &&
        sourcePosition
            .primary_home_for_ms >
        PRIMARY_HOME_GRACE_MS;

    if (
        !leavingHome &&
        !staleCatchUp &&
        (
            approachEntry ||
            isArrivalHome(
                sourcePosition
            )
        ) &&
        armed[source]
    ) {
        arrival = {
            _location_test:
                TEST_MODE,

            _location_test_case:
                TEST_MODE
                    ? (msg._location_test_case ?? null)
                    : undefined,

            payload: {
                contract:
                    "security.arrival.v1",

                kind:
                    "arrival",

                source,

                arriving: [
                    source
                ],

                arrival_source_type:
                    "person",

                arrival_stage:
                    approachEntry
                        ? "approach"
                        : "home",

                event_at:
                    sourcePosition
                        .updated_at ??
                    Date.now(),

                refresh_cycle_id:
                    msg.payload?.refresh_cycle_id
            }
        };
    }

    if (
        !approachEntry &&
        isArrivalHome(
            sourcePosition
        )
    ) {
        armed[source] =
            false;
    }
}


/* ================================
 * SNAPSHOT / REFRESH
 * ================================ */

if (!isLocationEvent) {
    for (
        const [
            name,
            item
        ]
        of Object.entries(
            people
        )
    ) {
        if (
            isArmingHome(
                item
            )
        ) {
            armed[name] =
                false;
        }
    }
}


/* ================================
 * DEDUPE CHEGADA
 * ================================ */

if (arrival) {
    const eventAt =
        sourcePosition
            ?.updated_at ??
        Date.now();

    const key =
        [
            source,
            arrival.payload
                .arrival_stage,
            triggerState ??
            "?",
            eventAt
        ].join(":");

    if (
        recovery
            .recent_arrivals[
        key
        ]
    ) {
        arrival = null;
    } else {
        recovery
            .recent_arrivals[
            key
        ] =
            Date.now();
    }
}


/* ================================
 * PERSISTÊNCIA
 * ================================ */

ctxSet(
    ARMED_KEY,
    armed
);

recovery.arrival_armed = {
    ...armed
};

recovery.valeria_notified =
    ctxGet(
        VALERIA_NOTIFY_KEY
    ) === true;

recovery.valeria_away_cycle =
    ctxGet(
        VALERIA_AWAY_CYCLE_KEY
    ) === true;

recovery.updated_at =
    Date.now();

ctxSet(
    RECOVERY_KEY,
    recovery,
    PERSISTENT
);


/* ================================
 * PEOPLE CONTEXT
 * ================================ */

const distances =
    Object.values(
        people
    )
        .map(
