}
ctxSet(ARMED_KEY, armed);
recovery.arrival_armed = armed;
if (inUse !== null) {
    recovery.in_use = inUse;
    recovery.last_confirmed_at = Date.now();
}
recovery.in_use_reason = inUseReason;
if (inUse !== null) recovery.trip_active = inUse === true && isAway(creta);
if (recovery.trip_active && !Number.isFinite(recovery.trip_started_at)) recovery.trip_started_at = Date.now();
if (inUse === false) recovery.trip_started_at = null;
recovery.updated_at = Date.now();
ctxSet(RECOVERY_KEY, recovery, PERSISTENT);

const engineUpdatedAt =
    observedAt(msg.payload?.creta_engine);

const lockUpdatedAt =
    observedAt(msg.payload?.creta_lock);

const lightingReady =
    creta.ready === true &&
    engineFresh === true &&
    (engineOn || engineOff);

const vehicleContext = {
    location: creta,
    distance_home_m: creta.distance_m,
    home: creta.ready ? isArrivalHome(creta) : null,
    away: creta.ready ? isAway(creta) : null,
    approaching_home:
        arrival?.payload?.arrival_stage === "approach",
    arrived_home:
        arrival?.payload?.arrival_stage === "home",

    engine_on: engineOn,
    engine_state: engineState,
    engine_state_valid: engineOn || engineOff,
    engine_stale: !engineFresh,
    engine_updated_at: engineUpdatedAt,

    lock_state: lockState,
    unlocked,
    lock_state_valid:
        lockFresh &&
        ["locked", "unlocked"].includes(lockState),
    lock_stale: !lockFresh,
    lock_updated_at: lockUpdatedAt,

    in_use: inUse,
    in_use_pending: inUse === null,
    in_use_reason: inUseReason,

    trip_active:
        inUse === true &&
        recovery.trip_active === true,
    trip_started_at:
        recovery.trip_started_at ?? null,

    state_valid: creta.state_valid,
    ready: creta.ready && inUse !== null,
    lighting_ready: lightingReady,
    stale: creta.stale || inUse === null,

    updated_at: Math.max(
        ...[
            creta.updated_at,
            engineUpdatedAt,
            lockUpdatedAt
        ].filter(Number.isFinite),
        0
    ),

    arrival_armed: armed,
};

/*
 * Confirma sucesso de refresh somente com evidência observável:
 * pelo menos um timestamp de localização/motor/trava precisa avançar
 * em relação ao baseline capturado imediatamente antes da tentativa.
 *
 * Se houve atualização, mas o alvo de readiness ainda não foi atingido,
 * NÃO cria cooldown de sucesso. Mantém o backoff da tentativa corrente
 * e permite novo retry.
 */
if (!TEST_MODE) {
    const refreshKey = "security_creta_refresh_v1";
    let refreshState =
        flow.get(refreshKey, "persistent");

    if (
        refreshState &&
        typeof refreshState === "object" &&
        refreshState.awaiting_evidence === true
    ) {
        const baseline =
            refreshState.baseline_observed_at ?? {};

        const currentObservedAt = {
            location:
                Number(vehicleContext.location?.updated_at ?? 0),
            engine:
                Number(vehicleContext.engine_updated_at ?? 0),
            lock:
                Number(vehicleContext.lock_updated_at ?? 0)
        };

        const changedDomains = [];

        for (const domain of ["location", "engine", "lock"]) {
            const before =
                Number(baseline[domain] ?? 0);
            const after =
                Number(currentObservedAt[domain] ?? 0);

            if (
                Number.isFinite(after) &&
                after > 0 &&
                (
                    !Number.isFinite(before) ||
                    before <= 0 ||
                    after > before
                )
            ) {
                changedDomains.push(domain);
            }
        }

        const lastAttemptAt =
            Number(refreshState.last_attempt_at ?? 0);

        const attemptCurrent =
            lastAttemptAt > 0 &&
            lastAttemptAt <= Date.now() + FUTURE_TOLERANCE_MS &&
            Date.now() - lastAttemptAt <= 5 * 60 * 1000;

        const evidenceObserved =
            attemptCurrent &&
            changedDomains.length > 0;

        const targetReady =
            vehicleContext.ready === true &&
            (
                refreshState.require_lighting_ready !== true ||
                vehicleContext.lighting_ready === true
            );

        if (evidenceObserved && targetReady) {
            refreshState = {
                ...refreshState,
                attempts: 0,
                last_success_at: Date.now(),
                next_allowed_at:
                    Date.now() + 15 * 60 * 1000,
                awaiting_evidence: false,
                last_evidence_at: Date.now(),
                last_evidence_domains: changedDomains,
                last_success_reason:
                    refreshState.require_lighting_ready === true
                        ? "fresh_entities_lighting_ready"
                        : "fresh_entities_context_ready",
                baseline_observed_at: null,
                require_lighting_ready: false,
                recovery_reason: null
            };

            flow.set(
                refreshKey,
                refreshState,
                "persistent"
            );

            node.status({
                fill: "green",
                shape: "dot",
                text:
                    refreshState.last_success_reason ===
                    "fresh_entities_lighting_ready"
                        ? "refresh confirmado; motor/contexto ready"
                        : "refresh confirmado; Creta ready"
            });
        } else if (evidenceObserved) {
            /*
             * Evidência parcial NÃO é sucesso. Não altera
             * next_allowed_at: o backoff calculado pela tentativa
             * corrente continua válido e haverá novo retry.
             */
            refreshState.last_partial_evidence_at =
                Date.now();
            refreshState.last_evidence_domains =
                changedDomains;
            refreshState.last_partial_reason =
                vehicleContext.ready !== true
                    ? "vehicle_context_still_pending"
                    : "lighting_context_still_pending";

            flow.set(
                refreshKey,
                refreshState,
                "persistent"
            );

            node.status({
                fill: "yellow",
                shape: "ring",
                text:
                    "refresh parcial; retry continuará"
            });
        }
    }
}
ctxSet("creta_context_v1", vehicleContext);
const previousReady = ctxGet("security_creta_ready_logged");
if (previousReady !== vehicleContext.ready) {
    node.log?.("contexto_creta: contexto " + (vehicleContext.ready ? "ready (" + vehicleContext.in_use_reason + ")" : "pending/stale"));
    ctxSet("security_creta_ready_logged", vehicleContext.ready);
}
msg.payload = {
    contract: "security.creta-context.v1", kind: "creta_context", context: vehicleContext,
    event: msg.payload?.event, reason: msg.payload?.reason ?? (vehicleContext.ready ? vehicleContext.in_use_reason : "vehicle_context_pending"), source: "creta",
    trigger_entity: msg.payload?.trigger_entity, trigger_state: triggerState, trigger_prev_state: triggerPrevState,
    confirmed_home_transition: isLocationEvent && creta.ready === true && triggerPrevValid && triggerState === "home" && triggerPrevState !== "home",
    refresh_cycle_id: msg.payload?.refresh_cycle_id,
    updated_at: vehicleContext.updated_at,
    valid: vehicleContext.state_valid,
    ready: vehicleContext.ready,
    lighting_ready: vehicleContext.lighting_ready,
    stale: vehicleContext.stale,
    readiness_reason:
        vehicleContext.ready
            ? vehicleContext.in_use_reason
            : "vehicle_context_pending",
};

if (TEST_MODE) {
    msg._location_test = true;
    msg._location_test_case = msg._location_test_case ?? null;
    msg.payload.test_mode = true;
    msg.payload.test_case = msg._location_test_case;

    if (arrival?.payload) {
        arrival._location_test = true;
        arrival._location_test_case = msg._location_test_case;
        arrival.payload.test_mode = true;
        arrival.payload.test_case = msg._location_test_case;
    }
}

let recoveryRequest = null;

/*
 * Se o próprio tracker do Creta acabou de se mover, mas o motor está
 * stale, pedir recovery imediatamente. Isso reduz a chance de o carro
 * já estar desligado quando o próximo tick periódico tentar atualizar.
 */
if (
    !TEST_MODE &&
    freshVehicleMovement &&
    engineFresh !== true
) {
    recoveryRequest = {
        payload: {
            kind: "refresh_tick",
            origin: "contexto_creta",
            reason:
                "creta_location_changed_engine_stale",
            force_recovery: true,
            require_lighting_ready: true,
            requested_at: Date.now()
        }
    };

    node.status({
        fill: "yellow",
        shape: "dot",
        text:
            "movimento do Creta; recovery do motor solicitado"
    });
}

return [msg, arrival, recoveryRequest];

const TEST_MODE =
    msg._location_test === true ||
    msg.payload?.test_mode === true;

if (TEST_MODE) {
    node.status({
        fill: "blue",
        shape: "dot",
        text: "TESTE: Bluelink suprimido"
    });
    return null;
}

if (msg.payload?.kind !== "refresh_command") return null;

const vehicleContext =
    flow.get("creta_context_v1") ?? {};

const contextReady =
    vehicleContext.ready === true;

const INTERVAL_MS = 15 * 60 * 1000;
const BASE_RETRY_MS = 60 * 1000;
const key = "security_creta_refresh_v1";

let state =
    flow.get(key, "persistent");

if (!state || typeof state !== "object") {
    state = {
        attempts: 0,
        last_success_at: 0,
        next_allowed_at: 0,
        last_attempt_at: 0,
        awaiting_evidence: false
    };
}

/*
 * Uma tentativa de recovery que ainda não atingiu o alvo continua sendo
 * recovery nos ticks seguintes, inclusive se o contexto genérico já ficou
 * ready. Isso é essencial para o caso "contexto ready, motor ainda stale".
 */
const outstandingRecovery =
    state.awaiting_evidence === true &&
    (
        state.require_lighting_ready === true ||
        (
            typeof state.recovery_reason === "string" &&
            state.recovery_reason.includes("recovery")
        )
    );

const recoveryNeeded =
    msg.payload?.recovery_needed === true ||
    msg.payload?.force_recovery === true ||
    msg.payload?.creta_ready === false ||
    contextReady !== true ||
    outstandingRecovery;

const requireLightingReady =
    msg.payload?.require_lighting_ready === true ||
    (
        state.awaiting_evidence === true &&
        state.require_lighting_ready === true
    );

const now = Date.now();

state.attempts = Number.isFinite(state.attempts)
    ? Math.max(0, Math.min(5, state.attempts))
    : 0;

if (
    !Number.isFinite(state.last_success_at) ||
    state.last_success_at > now + 60 * 1000
) {
    state.last_success_at = 0;
}

if (
    !Number.isFinite(state.next_allowed_at) ||
    state.next_allowed_at > now + INTERVAL_MS
) {
    state.next_allowed_at = 0;
}

if (
    !Number.isFinite(state.last_attempt_at) ||
    state.last_attempt_at > now + 60 * 1000
) {
    state.last_attempt_at = 0;
}

/*
 * Um recovery explícito (por exemplo, chegada recebida com motor stale)
 * pode quebrar o cooldown de SUCESSO de 15 min. Ele nunca quebra o
 * backoff de uma tentativa ainda aguardando evidência.
 */
const successCooldownActive =
    state.awaiting_evidence !== true &&
    state.last_success_at > 0 &&
    now < state.next_allowed_at;

if (recoveryNeeded && successCooldownActive) {
    state.next_allowed_at = 0;
}

const hour = new Date(now).getHours();
const daytime = hour >= 7 && hour < 22;

const enabled =
    recoveryNeeded ||
    msg.payload.anyone_away === true ||
    daytime;

if (!enabled) {
    node.status({
        fill: "grey",
        shape: "ring",
        text: "refresh Creta fora da janela"
    });
    flow.set(key, state, "persistent");
    return null;
}

/*
 * next_allowed_at representa backoff enquanto awaiting_evidence=true.
 * Não disparamos várias chamadas Bluelink para o mesmo recovery.
 */
if (now < state.next_allowed_at) {
    const waitS = Math.max(
        1,
        Math.ceil((state.next_allowed_at - now) / 1000)
    );

    node.status({
        fill: "grey",
        shape: "ring",
        text: state.awaiting_evidence === true
            ? `retry Bluelink em ${waitS}s`
            : `refresh Creta cooldown ${waitS}s`
    });

    flow.set(key, state, "persistent");
    return null;
}

/*
 * Um refresh normal respeita o intervalo de sucesso.
 * Recovery explícito pode rodar mesmo dentro desse intervalo.
 */
if (
    !recoveryNeeded &&
    state.last_success_at > 0 &&
    now - state.last_success_at < INTERVAL_MS
) {
    node.status({
        fill: "grey",
        shape: "ring",
        text: "Creta atualizado recentemente"
    });
    flow.set(key, state, "persistent");
    return null;
}

/*
 * Snapshot-base para comprovação do refresh.
 * O normalizador só considera evidência real se ao menos um destes
 * timestamps avançar em relação a esta tentativa.
 */
state.baseline_observed_at = {
    location: Number(vehicleContext.location?.updated_at ?? 0),
    engine: Number(vehicleContext.engine_updated_at ?? 0),
    lock: Number(vehicleContext.lock_updated_at ?? 0)
};

state.attempts =
    Math.min(5, Number(state.attempts || 0) + 1);

state.last_attempt_at = now;

state.next_allowed_at =
    now + Math.min(
        INTERVAL_MS,
        BASE_RETRY_MS * (2 ** (state.attempts - 1))
    );

state.awaiting_evidence = true;
state.last_attempt_cycle =
    msg.payload.refresh_cycle_id ?? null;

state.require_lighting_ready =
    requireLightingReady;

state.recovery_reason =
    msg.payload?.recovery_reason ??
    msg.payload?.reason ??
    (recoveryNeeded
        ? "readiness_recovery_needed"
        : "scheduled_refresh");

flow.set(key, state, "persistent");

msg.payload.retry_attempt = state.attempts;
msg.payload.refresh_requested_at = now;
msg.payload.creta_refresh_recovery = recoveryNeeded;
msg.payload.require_lighting_ready = requireLightingReady;
msg.payload.origin =
    msg.payload.origin ?? "contexto_chegadas";

node.status({
    fill: recoveryNeeded ? "yellow" : "green",
    shape: "dot",
    text: recoveryNeeded
        ? `Bluelink #${state.attempts}: ${requireLightingReady ? "recuperar motor/contexto" : "recuperar readiness"}`
        : `Bluelink #${state.attempts}: refresh real`
});

/*
 * Saída 1: força Bluelink + update_entity.
 * Saída 2: sincroniza trackers de pessoas.
 */
return [msg, msg];

if (msg.payload?.kind !== "arrival" || msg.payload?.arrival_source_type !== "creta") return null;

const TEST_MODE =
    msg._location_test === true ||
    msg.payload?.test_mode === true;

if (TEST_MODE) {
    node.status({
        fill: "blue",
        shape: "dot",
        text: "TESTE: ações reais do Creta suprimidas"
    });
    return [null, null];
}

const key = "security_creta_trip_action_v1";
const eventKey = [msg.payload.source, msg.payload.arrival_stage, msg.payload.event_at ?? msg.payload.trigger_state ?? "?"].join(":");
const previous = flow.get(key, "persistent");
const previousAt = Number(previous?.at ?? 0);
if (previous?.event_key === eventKey && previousAt <= Date.now() + 60 * 1000 && Date.now() - previousAt < 10 * 60 * 1000) return null;
flow.set(key, { version: 1, event_key: eventKey, at: Date.now() }, "persistent");
const wake = msg.payload.request_creta_wake === true ? msg : null;
return [wake, msg];

/*
 * O retorno de button.press significa apenas que o serviço foi aceito.
 * NÃO é evidência de que Bluelink atualizou as entidades.
 * Após o delay, inicia outro snapshot coordenado.
 */
msg._location_test = false;
delete msg._location_test_case;
msg.payload = {
    kind: "refresh_tick",
    origin: "contexto_creta",
    reason: "post_bluelink_recheck",
    requested_at: Date.now()
};
node.status({ fill: "blue", shape: "dot", text: "rechecando entidades após Bluelink" });
return msg;

const SHARED_TEST_KEY = "security_location_test_state_v1";

const TEST_KEYS = [
    "security_creta_recovery_v1__test",
    "creta_arrival_armed__test",
    "creta_in_use__test",
    "creta_context_v1__test",
    "security_creta_recovery_logged__test",
    "security_creta_ready_logged__test",
    "security_creta_test_clock"
];

const CASES = {
    creta_away: { state: "not_home", prev: "home", engine: "on", lock: "locked" },
    creta_approach: { state: "chegando", prev: "not_home", engine: "on", lock: "locked" },
    creta_home: { state: "home", prev: "chegando", engine: "on", lock: "locked" },
    creta_invalid_home: { state: "home", prev: "unknown", engine: "on", lock: "locked" },
    creta_invalid_approach: { state: "chegando", prev: "unavailable", engine: "on", lock: "locked" }
};

function baseline(now = Date.now()) {
    return {
        version: 1,
        gabriel: "home",
        valeria: "home",
        creta: "home",
        creta_engine: "off",
        creta_lock: "locked",
        observed_at: now,
        transitions: {}
    };
}

if (msg.test_case === "reset") {
    const now = Date.now();
    const resetState = baseline(now);
    resetState.reset_at = now;
    global.set(SHARED_TEST_KEY, resetState);

    for (const key of TEST_KEYS) {
        flow.set(key, undefined);
    }

    msg._location_test = true;
    msg._location_test_case = "reset";
    msg._location_test_reset = true;
    msg.payload = {
        kind: "test_reset",
        test_mode: true,
        test_case: "reset"
    };
    msg.topic = "security_context_refresh_test";

    node.status({
        fill: "blue",
        shape: "dot",
        text: "teste compartilhado resetado"
    });

    return msg;
}

const test = CASES[msg.test_case];
if (!test) {
    node.warn(
        "Caso de teste do Creta desconhecido: " +
        String(msg.test_case)
    );
    return null;
}

let state = global.get(SHARED_TEST_KEY);
if (!state || state.version !== 1) {
    state = baseline();
}

const now = Math.max(
    Date.now(),
    Number(state.observed_at || 0) + 1
);

/*
 * Altera SOMENTE o Creta.
 * Gabriel e Valéria permanecem no estado sintético acumulado.
 */
state.creta = test.state;
state.creta_engine = test.engine;
state.creta_lock = test.lock;
state.observed_at = now;
state.transitions = {
    creta: {
        domain: "creta",
    source: "creta",
    state: test.state,
    prev: test.prev,
    test_case: msg.test_case,
    at: now
    }
};

global.set(SHARED_TEST_KEY, state);

msg._location_test = true;
msg._location_test_case = msg.test_case;
msg.payload = {
    kind: "refresh_tick",
    test_mode: true,
    test_case: msg.test_case,
    test_state: {
        gabriel: state.gabriel,
        valeria: state.valeria,
        creta: state.creta,
        creta_engine: state.creta_engine,
        creta_lock: state.creta_lock
    }
};
msg.topic = "security_context_refresh_test";

node.status({
    fill: "green",
    shape: "dot",
    text: `Creta: ${test.prev} → ${test.state} | Valéria=${state.valeria}`
});

return msg;

const kind = msg.payload?.kind;
const FUTURE_TOLERANCE_MS = 60 * 1000;
const NOTIFICATION_TTL_MS = 10 * 60 * 1000;
const PENDING_NOTIFICATION_KEY = "security_pending_valeria_notification_v1";
const PERSISTENT = "persistent";

const TEST_MODE =
    msg._location_test === true ||
    msg.payload?.test_mode === true;

const TEST_CASE =
    msg._location_test_case ??
    msg.payload?.test_case ??
    null;

function contextKey(base) {
    return TEST_MODE ? `${base}__test` : base;
}

function ctxGet(base, store) {
    const key = contextKey(base);
    return TEST_MODE || !store
        ? flow.get(key)
        : flow.get(key, store);
}

function ctxSet(base, value, store) {
    const key = contextKey(base);
    return TEST_MODE || !store
        ? flow.set(key, value)
        : flow.set(key, value, store);
}

function nextRefreshCycle() {
    const key = "refresh_cycle_clock";
    const previous = Number(ctxGet(key) ?? 0);
    const cycle = Math.max(
        Date.now(),
        Number.isFinite(previous) ? previous + 1 : 0
    );
    ctxSet(key, cycle);
    return cycle;
}

function markTest(message) {
    if (!message || !TEST_MODE) return message;

    message._location_test = true;
    message._location_test_case = TEST_CASE;

    if (message.payload && typeof message.payload === "object") {
        message.payload.test_mode = true;
        message.payload.test_case = TEST_CASE;
    }

    return message;
}

function enrichNotification(payload, creta) {
    const byCar =
        creta?.ready === true &&
        creta.arrival_armed === true &&
        creta.distance_home_m !== null &&
        creta.distance_home_m <= 1500;

    const baseMessage = byCar
        ? "Valéria está chegando de carro."
        : "Valéria está chegando.";

    return {
        ...payload,
        by_car: byCar,
        creta_distance_m:
            creta?.ready === true
                ? creta.distance_home_m ?? null
                : null,
        message: TEST_MODE
            ? "[TESTE] " + baseMessage
            : baseMessage
    };
}

function validPending(pending, now) {
    return (
        pending &&
        pending.version === 1 &&
        pending.payload?.kind === "valeria_approach_notification" &&
        typeof pending.payload.notification_key === "string" &&
        pending.payload.notification_key.length > 0 &&
        Number.isFinite(pending.payload.event_at) &&
        Number.isFinite(pending.queued_at) &&
        pending.queued_at <= now + FUTURE_TOLERANCE_MS &&
        now - pending.queued_at <= NOTIFICATION_TTL_MS
    );
}

function newPending(cycle, options = {}) {
    return {
        cycle,
        people_received: false,
        creta_received: false,
        people_ready: false,
        creta_ready: false,
        emitted: false,
        started_at: cycle,
        force_recovery: options.force_recovery === true,
        require_lighting_ready: options.require_lighting_ready === true,
        request_reason: options.request_reason ?? null
    };
}

/* Reset de TESTE: usa somente caches __test. */
if (kind === "test_reset" && TEST_MODE) {
    ctxSet("refresh_pending", undefined);
    ctxSet("people_context_v1", undefined);
    ctxSet("creta_context_v1", undefined);
    ctxSet(PENDING_NOTIFICATION_KEY, undefined, PERSISTENT);

    const cycle = nextRefreshCycle();
    msg._location_test_reset = true;
    msg.payload = {
        contract: "security.snapshot-request.v1",
        kind: "snapshot_request",
        refresh_cycle_id: cycle,
        origin: "contexto_chegadas",
        reason: "manual_location_test_reset",
        requested_at: cycle
    };
    markTest(msg);

    node.status({
        fill: "blue",
        shape: "dot",
        text: "teste compartilhado resetado"
    });

    return [msg, null, null];
}

/*
 * Um refresh_tick sempre inicia um snapshot dos dois domínios.
 * A decisão de forçar refresh físico será feita DEPOIS que ambos
 * responderem, mesmo se um deles ainda estiver pending/stale.
 */
if (kind === "refresh_tick") {
    const requestedReason =
        msg.payload?.reason ?? "startup_or_periodic_reconciliation";
    const forceRecovery =
        msg.payload?.force_recovery === true;
    const requireLightingReady =
        msg.payload?.require_lighting_ready === true;

    /*
     * Evita que o tick periódico de 30 s sobrescreva um ciclo de recovery
     * que ainda está esperando os snapshots. Se já existe um ciclo em voo,
     * uma solicitação mais forte apenas promove esse ciclo para recovery.
     */
    const currentPending =
        ctxGet("refresh_pending");

    const currentInFlight =
        currentPending &&
        currentPending.emitted !== true &&
        Number.isFinite(
            Number(currentPending.started_at)
        ) &&
        Date.now() -
            Number(currentPending.started_at) <
            10 * 1000;

    if (currentInFlight) {
        if (forceRecovery) {
            currentPending.force_recovery = true;
            currentPending.require_lighting_ready =
                currentPending.require_lighting_ready === true ||
                requireLightingReady;
            currentPending.request_reason =
                requestedReason;

            ctxSet(
                "refresh_pending",
                currentPending
            );

            node.status({
                fill: "yellow",
                shape: "ring",
                text: "ciclo em voo promovido para recovery"
            });
        }

        return null;
    }

    const cycle = nextRefreshCycle();

    ctxSet(
        "refresh_pending",
        newPending(cycle, {
            force_recovery: forceRecovery,
            require_lighting_ready: requireLightingReady,
            request_reason: requestedReason
        })
    );

    msg.payload = {
        contract: "security.snapshot-request.v1",
        kind: "snapshot_request",
        refresh_cycle_id: cycle,
        origin: "contexto_chegadas",
        reason: TEST_MODE
            ? "manual_location_test"
            : requestedReason,
        force_recovery: forceRecovery,
        require_lighting_ready: requireLightingReady,
        requested_at: cycle
    };

    markTest(msg);
    return [msg, null, null];
}

if (kind === "people_context" || kind === "creta_context") {
    const domain = kind === "people_context" ? "people" : "creta";
    const key = domain + "_context_v1";
    const previous = ctxGet(key);

    const incomingAt = Number(
        msg.payload.updated_at ??
        msg.payload.context?.updated_at ??
        0
    );
    const previousAt = Number(previous?.updated_at ?? 0);

    let cached = previous;
    let accepted = false;
    let rejectedReason = null;

    if (incomingAt > Date.now() + FUTURE_TOLERANCE_MS) {
        rejectedReason = "future_timestamp";
        node.warn(
            "contexto_chegadas: snapshot " + domain +
            (TEST_MODE ? " [TESTE]" : "") +
            " no futuro; cache atual preservado"
        );
    } else if (
        previous &&
        incomingAt &&
        previousAt &&
        incomingAt < previousAt
    ) {
        rejectedReason = "out_of_order";
        node.warn(
            "contexto_chegadas: snapshot " + domain +
            (TEST_MODE ? " [TESTE]" : "") +
            " fora de ordem; cache atual preservado"
        );
    } else if (
        !previous ||
        (incomingAt && (!previousAt || incomingAt > previousAt))
    ) {
        ctxSet(key, msg.payload.context);
        cached = msg.payload.context;
        accepted = true;
    } else if (!incomingAt) {
        rejectedReason = "missing_timestamp";
        node.warn(
            "contexto_chegadas: snapshot " + domain +
            " sem timestamp; cache atual preservado"
        );
    } else if (
        incomingAt === previousAt &&
        JSON.stringify(previous) !== JSON.stringify(msg.payload.context)
    ) {
        /* Mesmo timestamp da fonte; aceita mudança de estado derivado. */
        ctxSet(key, msg.payload.context);
        cached = msg.payload.context;
        accepted = true;
        node.status({
            fill: "yellow",
            shape: "dot",
            text: "contexto " + domain + " atualizado no mesmo timestamp"
        });
    }

    let refresh = null;
    const pending = ctxGet("refresh_pending");

    if (
        pending &&
        msg.payload.refresh_cycle_id === pending.cycle
    ) {
        /*
         * IMPORTANTE: "recebeu snapshot" e "snapshot ready" são coisas
         * diferentes. O v7 usava ready como confirmação de recebimento,
         * impedindo justamente o refresh que recuperaria um domínio stale.
         */
        pending[domain + "_received"] = true;
        pending[domain + "_ready"] = accepted
            ? msg.payload.ready === true
            : cached?.ready === true;

        if (
            pending.people_received &&
            pending.creta_received &&
            !pending.emitted
        ) {
            pending.emitted = true;

            const people = ctxGet("people_context_v1") ?? {};
            const creta = ctxGet("creta_context_v1") ?? {};
            const contextsReady =
                pending.people_ready === true &&
                pending.creta_ready === true;

            const recoveryNeeded =
                !contextsReady ||
                pending.force_recovery === true;

            const recoveryReason =
                pending.request_reason ??
                (contextsReady
                    ? "paired_ready_snapshots"
                    : "readiness_recovery_needed");

            refresh = {
                payload: {
                    contract: "security.refresh-command.v1",
                    kind: "refresh_command",
                    refresh_cycle_id: pending.cycle,
                    anyone_away:
                        people?.anyone_away === true ||
                        creta?.away === true,
                    people_ready: pending.people_ready === true,
                    creta_ready: pending.creta_ready === true,
                    contexts_ready: contextsReady,
                    recovery_needed: recoveryNeeded,
                    force_recovery: pending.force_recovery === true,
                    require_lighting_ready:
                        pending.require_lighting_ready === true,
                    recovery_reason: recoveryReason,
                    origin: "contexto_chegadas",
                    reason: TEST_MODE
                        ? (recoveryNeeded
                            ? "test_readiness_recovery_needed"
                            : "paired_ready_test_snapshots")
                        : (recoveryNeeded
                            ? recoveryReason
                            : "paired_ready_snapshots"),
                    issued_at: Date.now(),
                    ready: contextsReady,
                    rejected_snapshot_reason: rejectedReason
                }
            };

            markTest(refresh);

            node.status({
                fill: recoveryNeeded ? "yellow" : "green",
                shape: "dot",
                text: recoveryNeeded
                    ? "refresh de recuperação emitido"
                    : "snapshots ready; política de refresh emitida"
            });
        }

        ctxSet("refresh_pending", pending);
    }

    let notification = null;
    let queued = ctxGet(PENDING_NOTIFICATION_KEY, PERSISTENT);

    if (queued && !validPending(queued, Date.now())) {
        ctxSet(PENDING_NOTIFICATION_KEY, null, PERSISTENT);
        queued = null;
        node.warn(
            "contexto_chegadas: aviso pendente da Valéria inválido ou expirado; descartado"
        );
    }

    const creta = ctxGet("creta_context_v1");
    if (domain === "creta" && creta?.ready === true && queued) {
        ctxSet(PENDING_NOTIFICATION_KEY, null, PERSISTENT);
        notification = {
            payload: enrichNotification(queued.payload, creta)
        };
        markTest(notification);
        node.log?.(
            "contexto_chegadas: aviso pendente da Valéria liberado após readiness do Creta"
        );
    }

    return refresh || notification
        ? [null, refresh, notification]
        : null;
}

if (kind === "valeria_approach_notification") {
    const creta = ctxGet("creta_context_v1");

    if (creta?.ready === true) {
        ctxSet(PENDING_NOTIFICATION_KEY, null, PERSISTENT);
        msg.payload = enrichNotification(msg.payload, creta);
        markTest(msg);
        return [null, null, msg];
    }

    const queuedAt = Date.now();
    const existing = ctxGet(PENDING_NOTIFICATION_KEY, PERSISTENT);

    if (
        !validPending(existing, queuedAt) ||
        existing.payload.notification_key !== msg.payload.notification_key
    ) {
        ctxSet(
            PENDING_NOTIFICATION_KEY,
            {
                version: 1,
                queued_at: queuedAt,
                payload: { ...msg.payload }
            },
            PERSISTENT
        );
        node.log?.(
            "contexto_chegadas: aviso da Valéria aguardando readiness do Creta"
        );
    }

    return null;
}

return null;

const kind = msg.payload?.kind;

const TEST_MODE =
    msg._location_test === true ||
    msg.payload?.test_mode === true;

const TEST_CASE =
    msg._location_test_case ??
    msg.payload?.test_case ??
    null;

const incomingAt = Number(
    msg.payload?.updated_at ??
    msg.payload?.context?.updated_at ??
    0
);

const FUTURE_TOLERANCE_MS = 60 * 1000;
const PENDING_ARRIVAL_TTL_MS = 2 * 60 * 1000;

function contextKey(base) {
    return TEST_MODE ? `${base}__test` : base;
}

function updateCache(baseKey) {
    const key = contextKey(baseKey);
    const old = flow.get(key);
    const oldAt = Number(old?.updated_at ?? 0);

    if (
        incomingAt > Date.now() + FUTURE_TOLERANCE_MS ||
        (
            old &&
            incomingAt &&
            oldAt &&
            incomingAt < oldAt
        )
    ) {
        node.warn(
            "iluminacao_seguranca: snapshot" +
            (TEST_MODE ? " [TESTE]" : "") +
            " fora de ordem ou no futuro; descartado"
        );
        return false;
    }

    if (
        !old ||
        (
            incomingAt &&
            (!oldAt || incomingAt > oldAt)
        )
    ) {
        flow.set(key, msg.payload.context);
        return true;
    }

    if (!incomingAt) {
        node.warn(
            "iluminacao_seguranca: snapshot sem timestamp; cache atual preservado"
        );
        return false;
    }

    if (
        incomingAt === oldAt &&
        JSON.stringify(old) !==
            JSON.stringify(msg.payload.context)
    ) {
        /*
         * Mesmo timestamp de origem, mas estado derivado diferente.
         * A versão recebida por último é a interpretação mais recente.
         */
        flow.set(key, msg.payload.context);

        node.status({
            fill: "yellow",
            shape: "dot",
            text: "contexto atualizado no mesmo timestamp"
        });

        return true;
    }

    return false;
}

let contextAccepted = true;

if (kind === "people_context") {
    contextAccepted =
        updateCache("people_context_v1");
}

if (kind === "creta_context") {
    contextAccepted =
        updateCache("creta_context_v1");
}

if (kind === "sun_context") {
    flow.set(
        "sun_below_horizon",
        msg.payload.sun_below_horizon === true
    );
}

/*
 * RESET de cenário sintético também elimina qualquer chegada pendente
 * daquele cenário. A fila de produção usa outra chave e não é tocada.
 */
if (
    TEST_MODE &&
    msg._location_test_reset === true
) {
    flow.set(
        contextKey("security_light_pending_arrival_v1"),
        null
    );
}

/*
 * Contexto sintético não dispara reconciliação física.
 */
const reconcile =
    TEST_MODE
        ? null
        : {
            payload: {
                kind: "reconcile_signal",
                reason: "context_update"
            }
        };

const creta =
    flow.get(
        contextKey("creta_context_v1")
    ) ?? {};

const lifecycle =
    flow.get(
        "security_light_lifecycle_v1",
        "persistent"
    ) ?? {};

const original = msg.payload;

/*
 * Reprocessa uma chegada curta que chegou enquanto o contexto do
 * Creta/motor ainda estava em recovery. O reprocessamento acontece
 * somente quando já existem dados suficientes para decidir e dentro
 * de uma janela curta, evitando acender por uma chegada antiga.
 */
const pendingKey =
    contextKey(
        "security_light_pending_arrival_v1"
    );

let pending =
    flow.get(pendingKey);

let replay = null;

if (pending) {
    const queuedAt =
        Number(pending.queued_at ?? 0);

    const expiresAt =
        Number(pending.expires_at ?? 0);

    const validPending =
        pending.version === 1 &&
        pending.message &&
        Number.isFinite(queuedAt) &&
        Number.isFinite(expiresAt) &&
        queuedAt <= Date.now() + FUTURE_TOLERANCE_MS &&
        Date.now() <= expiresAt &&
        expiresAt - queuedAt <=
            PENDING_ARRIVAL_TTL_MS + 1000;

    if (!validPending) {
        flow.set(pendingKey, null);

        node.warn(
            "iluminacao_seguranca: chegada pendente expirou " +
            "antes da recuperação do contexto"
        );

        pending = null;
    }
}

const cretaLightingReady =
    creta.ready === true &&
    (
        creta.lighting_ready === true ||
        (
            creta.engine_state_valid === true &&
            creta.engine_stale !== true
        )
    );

const replayReady =
    pending &&
    cretaLightingReady &&
    flow.get("sun_ready") === true;

if (replayReady) {
    replay = {
        ...pending.message,
        payload: {
            ...(pending.message.payload ?? {}),
            arrival_replayed_after_context_recovery: true,
            arrival_originally_queued_at:
                pending.queued_at,
            arrival_replayed_at:
                Date.now()
        }
    };

    replay._arrival_replay = true;

    if (TEST_MODE) {
        replay._location_test = true;
        replay._location_test_case =
            TEST_CASE ??
            pending.message._location_test_case ??
            null;

        replay.payload.test_mode = true;
        replay.payload.test_case =
            replay._location_test_case;
    }

    flow.set(pendingKey, null);

    node.status({
        fill: "green",
        shape: "dot",
        text: "chegada pendente reprocessada após recovery"
    });
}

/*
 * Saída 1 mantém o processamento normal de contexto/lifecycle.
 * Se o snapshot de Pessoas/Creta foi rejeitado, não propaga esse
 * contexto para regras de desligamento, mas ainda permite replay
 * baseado no cache válido já existente.
 */
let lifecycleMsg = msg;

if (
    (
        kind === "people_context" ||
        kind === "creta_context"
    ) &&
    !contextAccepted
) {
    lifecycleMsg = null;
}

if (lifecycleMsg) {
    lifecycleMsg.payload = {
        event:
            original?.event ??
            "context_update",
        reason:
            original?.reason,
        source:
            original?.source,
        trigger_state:
            original?.trigger_state,
        trigger_prev_state:
            original?.trigger_prev_state,
        confirmed_home_transition:
            original?.confirmed_home_transition === true,
        creta_ready:
            creta.ready === true,
        creta_lighting_ready:
            cretaLightingReady,
        creta_engine_on:
            creta.engine_on,
        creta_engine_state_valid:
            creta.engine_state_valid === true,
        creta_unlocked:
            creta.unlocked,
        creta_in_use:
            creta.in_use,
        active:
            lifecycle.active_by_arrival === true
    };

    if (TEST_MODE) {
        lifecycleMsg._location_test = true;
        lifecycleMsg._location_test_case =
            TEST_CASE;

        lifecycleMsg.payload.test_mode = true;
        lifecycleMsg.payload.test_case =
            TEST_CASE;
    }
}

/*
 * OUTPUT 1 = contexto para lifecycle/desligamento
 * OUTPUT 2 = sinal de reconciliação física
 * OUTPUT 3 = arrival reprocessado após recovery
 */
return [
    lifecycleMsg,
    reconcile,
    replay
];

if (msg.payload?.kind !== "arrival") {
    return null;
}

const TEST_MODE =
    msg._location_test === true ||
    msg.payload?.test_mode === true;

const TEST_CASE =
    msg._location_test_case ??
    msg.payload?.test_case ??
    null;

const PENDING_ARRIVAL_TTL_MS =
    2 * 60 * 1000;

const RECOVERY_REQUEST_THROTTLE_MS =
    30 * 1000;

function contextKey(base) {
    return TEST_MODE
        ? `${base}__test`
        : base;
}

const creta =
    flow.get(
        contextKey("creta_context_v1")
    ) ?? {};

const people =
    flow.get(
        contextKey("people_context_v1")
    ) ?? {};

const lifecycle =
    flow.get(
        "security_light_lifecycle_v1",
        "persistent"
    ) ?? {};

const physical =
    flow.get(
        "security_light_physical_state"
    ) ?? "unknown";

const physicalObservedAt =
    Number(
        flow.get(
            "security_light_physical_observed_at"
        ) ?? 0
    );

const physicalFresh =
    Number.isFinite(physicalObservedAt) &&
    physicalObservedAt <=
        Date.now() + 60 * 1000 &&
    Date.now() - physicalObservedAt <=
        2 * 60 * 1000;

const lightReconciled =
    flow.get("light_reconciled") === true;

const sunReady =
    flow.get("sun_ready") === true;

const cretaLightingReady =
    creta.ready === true &&
    (
        creta.lighting_ready === true ||
        (
            creta.engine_state_valid === true &&
            creta.engine_stale !== true
        )
    );

/*
 * Para a decisão física de acendimento não basta um contexto inferido:
 * precisamos conseguir afirmar o estado atual do motor.
 */
const logicReady =
    cretaLightingReady &&
    sunReady;

const diagnostic = {
    ...msg,
    payload: {
        ...(msg.payload ?? {}),
        diagnostic:
            "arrival_trigger_received",
        gps_trigger_functional: true,
        decision_context_ready:
            logicReady,
        people_context_ready:
            people.ready === true,
        creta_context_ready:
            creta.ready === true,
        creta_lighting_ready:
            cretaLightingReady,
        creta_engine_state_valid:
            creta.engine_state_valid === true,
        creta_engine_stale:
            creta.engine_stale === true,
        sun_ready:
            sunReady,
        sun_below_horizon:
            flow.get(
                "sun_below_horizon"
            ) === true,
        creta_in_use:
            creta.in_use,
        creta_engine_on:
            creta.engine_on,
        reflector_state:
            physical,
        reflector_physical_fresh:
            physicalFresh,
        reflector_reconciled:
            lightReconciled,
        would_evaluate_turn_on:
            logicReady,
        arrival_replay:
            msg._arrival_replay === true
    }
};

if (TEST_MODE) {
    diagnostic._location_test = true;
    diagnostic._location_test_case =
        TEST_CASE;
    diagnostic.payload.test_mode = true;
    diagnostic.payload.test_case =
        TEST_CASE;
}

node.status({
    fill: logicReady
        ? "green"
        : "yellow",
    shape: "dot",
    text:
        `${TEST_MODE ? "TESTE " : ""}` +
        `GPS ${msg.payload.source}/${msg.payload.arrival_stage} | ` +
        (
            logicReady
                ? "motor/contextos OK"
                : (
                    !cretaLightingReady
                        ? "Creta/motor pendente"
                        : "luminosidade pendente"
                )
        ) +
        ` | ${
            flow.get(
                "sun_below_horizon"
            ) === true
                ? "escuro"
                : "claro"
        }`
});

let recoveryRequest = null;

if (!logicReady) {
    /*
     * Não perde a chegada. Guarda por no máximo 2 minutos para que
     * Atualizar contexto de alto nível a reenvie a este nó quando o
     * recovery do Creta/motor terminar.
     */
    const pendingKey =
        contextKey(
            "security_light_pending_arrival_v1"
        );

    const now =
        Date.now();

    const originalQueuedAt =
        Number(
            msg.payload
                ?.arrival_originally_queued_at ??
            now
        );

    const queuedAt =
        Number.isFinite(originalQueuedAt) &&
        originalQueuedAt > 0
            ? originalQueuedAt
            : now;

    const expiresAt =
        queuedAt +
        PENDING_ARRIVAL_TTL_MS;

    const eventAt =
        Number(
            msg.payload?.event_at ??
            msg.payload?.updated_at ??
            now
        );

    const existing =
        flow.get(pendingKey);

    const existingEventAt =
        Number(
            existing?.event_at ?? 0
        );

    /*
     * Mantém o evento mais recente, mas um replay não estende a TTL.
     */
    if (
        !existing ||
        !Number.isFinite(existingEventAt) ||
        eventAt >= existingEventAt
    ) {
        flow.set(
            pendingKey,
            {
                version: 1,
                queued_at:
                    queuedAt,
                expires_at:
                    expiresAt,
                event_at:
                    eventAt,
                message: {
                    ...msg,
                    payload: {
                        ...(msg.payload ?? {})
                    }
                }
            }
        );
    }

    diagnostic.payload
        .pending_arrival_queued = true;

    diagnostic.payload
        .pending_arrival_expires_at =
            expiresAt;

    /*
     * Se o que falta é o Creta/motor, força recovery imediatamente.
     * Se só falta luminosidade, o próprio sun_context fará o replay.
     */
    if (!cretaLightingReady) {
        const recoveryKey =
            contextKey(
                "security_light_last_recovery_request_at"
            );

        const lastRecoveryAt =
            Number(
                flow.get(recoveryKey) ?? 0
            );

        const canRequest =
            !Number.isFinite(lastRecoveryAt) ||
            lastRecoveryAt <= 0 ||
            now - lastRecoveryAt >=
                RECOVERY_REQUEST_THROTTLE_MS;

        if (canRequest) {
            flow.set(
                recoveryKey,
                now
            );

            const recoveryReason =
                creta.ready === true
                    ? "arrival_engine_recovery_needed"
                    : "arrival_creta_context_recovery_needed";

            recoveryRequest = {
                _location_test:
                    TEST_MODE,
                _location_test_case:
                    TEST_CASE,
                payload: {
                    kind:
                        "refresh_tick",
                    origin:
                        "iluminacao_seguranca",
                    reason:
                        recoveryReason,
                    force_recovery:
                        true,
                    require_lighting_ready:
                        true,
                    requested_at:
                        now,
                    arrival_source:
                        msg.payload.source,
                    arrival_stage:
                        msg.payload.arrival_stage,
                    test_mode:
                        TEST_MODE,
                    test_case:
                        TEST_CASE
                }
            };

            diagnostic.payload
                .context_recovery_requested =
                    true;

            diagnostic.payload
                .context_recovery_reason =
                    recoveryReason;
        } else {
            diagnostic.payload
                .context_recovery_requested =
                    false;

            diagnostic.payload
                .context_recovery_throttled =
                    true;
        }
    }

    node.warn(
        "iluminacao_seguranca: trigger de chegada recebido; " +
        (
            !cretaLightingReady
                ? "Creta/motor ainda não ready — chegada preservada para replay"
                : "luminosidade ainda não ready — chegada preservada para replay"
        )
    );

    /*
     * OUTPUT 1 = decisão normal
     * OUTPUT 2 = diagnóstico GPS
     * OUTPUT 3 = recovery imediato de contexto
     */
    return [
        null,
        diagnostic,
        recoveryRequest
    ];
}

/*
 * Se chegamos aqui, o evento atual já pode ser decidido.
 * Remove uma fila anterior para impedir replay duplicado.
 */
flow.set(
    contextKey(
        "security_light_pending_arrival_v1"
    ),
    null
);

const eventAt =
    Number(
        msg.payload.event_at ??
        msg.payload.updated_at ??
        Date.now()
    );

msg.payload.arrival_key = [
    msg.payload.source,
    msg.payload.arrival_stage,
    eventAt
].join(":");

msg.payload.sun_below_horizon =
    flow.get(
        "sun_below_horizon"
    ) === true;

msg.payload.creta_in_use =
    creta.in_use;

msg.payload.creta_engine_on =
    creta.engine_on;

msg.payload.creta_engine_state_valid =
    creta.engine_state_valid === true;

msg.payload.creta_lighting_ready =
    cretaLightingReady;

msg.payload.active =
    lifecycle.active_by_arrival === true ||
    physical === "on";

msg.payload.reflector_state =
    physical;

msg.payload.reflector_physical_fresh =
    physicalFresh;

msg.payload.reflector_reconciled =
    lightReconciled;

if (TEST_MODE) {
    msg._location_test = true;
    msg._location_test_case =
        TEST_CASE;
    msg.payload.test_mode = true;
    msg.payload.test_case =
        TEST_CASE;
}

/*
 * OUTPUT 1 = continua avaliando acendimento.
 * OUTPUT 2 = diagnóstico do trigger GPS/chegada.
 * OUTPUT 3 = recovery imediato quando contexto insuficiente.
 */
return [
    msg,
    diagnostic,
    null
];

/*
 * Regra física v9:
 * o refletor só pode ser ligado quando o Creta está efetivamente em uso
 * E o motor atual foi observado ligado/running.
 *
 * Evidência persistida ou movimento do tracker podem pedir recovery,
 * mas nunca autorizam sozinhos switch.turn_on.
 */
if (
    msg.payload?.creta_in_use !== true ||
    msg.payload?.creta_engine_on !== true ||
    msg.payload?.creta_engine_state_valid !== true
) {
    node.status({
        fill: "yellow",
        shape: "ring",
        text: "Creta sem motor ON atual"
    });
    return null;
}

const lifecycle =
    flow.get(
        "security_light_lifecycle_v1",
