msg.notification_message =
    (labels[msg.arrival_source] || msg.arrival_source) +
    " está chegando. Deseja desarmar o alarme da casa?";

node.status({
    fill: "yellow",
    shape: "dot",
    text: "aguardando confirmacao real"
});

return msg;

const PENDING_KEY =
    "alarm_arrival_pending_confirmation";

const TEST_PENDING_KEY =
    "alarm_arrival_test_pending_confirmation";

const pending = flow.get(PENDING_KEY);
let testPending = flow.get(TEST_PENDING_KEY);

/*
 * Formato observado no Home Assistant:
 * msg.payload.event.action
 *
 * Os fallbacks deixam o fluxo tolerante a pequenas diferenças de
 * serialização sem aceitar uma action arbitrária.
 */
const action =
    msg.payload?.event?.action ??
    msg.payload?.action ??
    msg.event?.action ??
    null;

if (
    typeof action !== "string" ||
    action.length === 0
) {
    node.status({
        fill: "red",
        shape: "ring",
        text: "evento sem action"
    });

    return [null, null];
}

const now = Date.now();

/*
 * Uma action de TESTE só é válida se a pendência tiver sido criada
 * depois do reset mais recente, seja ele vindo dos testes de localização
 * ou do botão RESETAR teste do alarme desta própria aba.
 */
const sharedTestState =
    global.get("security_location_test_state_v1") ?? {};

const locationResetAt =
    Number(sharedTestState.reset_at ?? 0);

const alarmResetAt =
    Number(global.get("alarm_arrival_test_reset_at") ?? 0);

const latestTestResetAt = Math.max(
    Number.isFinite(locationResetAt) && locationResetAt > 0
        ? locationResetAt
        : 0,
    Number.isFinite(alarmResetAt) && alarmResetAt > 0
        ? alarmResetAt
        : 0
);

if (testPending) {
    const createdAt = Number(testPending.createdAt ?? 0);

    if (
        latestTestResetAt > 0 &&
        (
            !Number.isFinite(createdAt) ||
            createdAt <= latestTestResetAt
        )
    ) {
        flow.set(TEST_PENDING_KEY, null);
        testPending = null;
    }
}

const isTestAction =
    action.startsWith("ALARME_TESTE_");

/*
 * Nunca deixa uma action de teste antiga cair na trilha real.
 */
if (isTestAction && !testPending) {
    node.status({
        fill: "grey",
        shape: "ring",
        text: "action TESTE sem pendencia valida (reset/expirada)"
    });

    return [null, null];
}

if (
    isTestAction &&
    testPending &&
    action !== testPending.confirmAction &&
    action !== testPending.cancelAction
) {
    node.status({
        fill: "grey",
        shape: "ring",
        text: "action TESTE de token antigo ignorada"
    });

    return [null, null];
}


// ======================================================
// TESTE
// Nunca envia mensagem para o desarme real
// ======================================================

if (
    testPending &&
    (
        action === testPending.confirmAction ||
        action === testPending.cancelAction
    )
) {
    if (
        !Number.isFinite(Number(testPending.expiresAt)) ||
        now > Number(testPending.expiresAt)
    ) {
        flow.set(TEST_PENDING_KEY, null);

        node.status({
            fill: "grey",
            shape: "ring",
            text: "teste expirado"
        });

        return [null, null];
    }

    flow.set(TEST_PENDING_KEY, null);

    msg._location_test = true;
    msg._location_test_case =
        testPending.testCase ?? null;

    msg.alarm_arrival_test = true;
    msg.alarm_arrival_test_action = action;
    msg.arrival_source =
        testPending.source ?? "manual";
    msg.arrival_stage =
        testPending.stage ?? "manual";
    msg.refresh_cycle_id =
        testPending.refreshCycleId ?? null;

    if (action === testPending.confirmAction) {
        msg.alarm_arrival_test_result =
            "confirmado";

        node.status({
            fill: "green",
            shape: "dot",
            text: "teste confirmado - sem desarme"
        });
    } else {
        msg.alarm_arrival_test_result =
            "cancelado";

        node.status({
            fill: "blue",
            shape: "dot",
            text: "teste cancelado - sem desarme"
        });
    }

    // Saída 2 = somente diagnóstico/teste.
    return [null, msg];
}


// ======================================================
// CONFIRMAÇÃO REAL
// ======================================================

if (!pending) {
    node.status({
        fill: "grey",
        shape: "ring",
        text: "sem confirmacao pendente"
    });

    return [null, null];
}

if (
    !Number.isFinite(Number(pending.expiresAt)) ||
    now > Number(pending.expiresAt)
) {
    flow.set(PENDING_KEY, null);

    node.status({
        fill: "grey",
        shape: "ring",
        text: "confirmacao expirada"
    });

    return [null, null];
}

if (action === pending.cancelAction) {
    flow.set(PENDING_KEY, null);

    node.status({
        fill: "blue",
        shape: "ring",
        text: "alarme mantido armado"
    });

    return [null, null];
}

/*
 * A action não pertence à confirmação real atual.
 * Mantém a pendência para permitir a resposta correta depois.
 */
if (action !== pending.confirmAction) {
    node.status({
        fill: "grey",
        shape: "ring",
        text: "action nao corresponde"
    });

    return [null, null];
}


// ======================================================
// DESARME CONFIRMADO
// ======================================================

flow.set(PENDING_KEY, null);

msg.arrival_source = pending.source;
msg.arrival_stage = pending.stage;
msg.refresh_cycle_id =
    pending.refreshCycleId ?? null;

msg.alarm_disarm_automatic = true;
msg.alarm_disarm_confirmed = true;

msg.alarm_disarm_reason =
    "chegada_confirmada_" +
    pending.source +
    "_" +
    pending.stage;

msg.alarm_disarm_confirmed_by =
    msg.payload?.context?.user_id ??
    msg.payload?.event?.context?.user_id ??
    "home_assistant";

node.status({
    fill: "green",
    shape: "dot",
    text: "desarme confirmado"
});

// Saída 1 = desarme real.
return [msg, null];

const TEST_PENDING_KEY =
    "alarm_arrival_test_pending_confirmation";

const TEST_TTL_MS = 2 * 60 * 1000;
const now = Date.now();

let existing = flow.get(TEST_PENDING_KEY);

/*
 * RESETAR testes de Pessoas/Creta grava reset_at no estado global
 * compartilhado. Uma confirmação sintética criada antes desse reset
 * não pode bloquear o próximo cenário. A pendência REAL do alarme
 * usa outra chave e nunca é alterada aqui.
 */
const sharedTestState =
    global.get("security_location_test_state_v1") ?? {};

const locationResetAt =
    Number(sharedTestState.reset_at ?? 0);

const alarmResetAt =
    Number(global.get("alarm_arrival_test_reset_at") ?? 0);

const resetAt = Math.max(
    Number.isFinite(locationResetAt) && locationResetAt > 0
        ? locationResetAt
        : 0,
    Number.isFinite(alarmResetAt) && alarmResetAt > 0
        ? alarmResetAt
        : 0
);

const existingCreatedAt =
    Number(existing?.createdAt ?? 0);

if (
    existing &&
    resetAt > 0 &&
    (
        !Number.isFinite(existingCreatedAt) ||
        existingCreatedAt <= resetAt
    )
) {
    flow.set(TEST_PENDING_KEY, null);
    existing = null;
}

if (
    existing &&
    (
        !Number.isFinite(Number(existing.expiresAt)) ||
        Number(existing.expiresAt) <= now
    )
) {
    flow.set(TEST_PENDING_KEY, null);
    existing = null;
}

const source =
    msg.arrival_source ??
    msg.payload?.source ??
    "manual";

const stage =
    msg.arrival_stage ??
    msg.payload?.arrival_stage ??
    "manual";

const testCase =
    msg._location_test_case ??
    msg.payload?.test_case ??
    "manual_notification_test";

const refreshCycleId =
    msg.payload?.refresh_cycle_id ??
    null;

/*
 * No cenário combinado, Valéria e Creta podem emitir arrival no
 * mesmo ciclo. Não sobrescreve uma confirmação de TESTE ainda válida.
 */
if (existing?.expiresAt > now) {
    const sameCycle =
        refreshCycleId !== null &&
        existing.refreshCycleId !== null &&
        String(existing.refreshCycleId) ===
            String(refreshCycleId);

    const sameCase =
        existing.testCase === testCase;

    node.status({
        fill: "grey",
        shape: "ring",
        text:
            sameCycle || sameCase
                ? "confirmacao TESTE ja pendente neste cenario"
                : "outra confirmacao TESTE ainda pendente"
    });

    return null;
}

const token =
    (
        now.toString(36) +
        "_" +
        Math.random().toString(36).slice(2, 10)
    ).toUpperCase();

const confirmAction =
    "ALARME_TESTE_CONFIRMAR_" + token;

const cancelAction =
    "ALARME_TESTE_CANCELAR_" + token;

const labels = {
    gabriel: "Gabriel",
    valeria: "Valéria",
    creta: "Creta",
    manual: "Teste manual"
};

flow.set(TEST_PENDING_KEY, {
    version: 1,
    confirmAction,
    cancelAction,
    createdAt: Math.max(now, resetAt + 1),
    expiresAt: Math.max(now, resetAt + 1) + TEST_TTL_MS,
    source,
    stage,
    testCase,
    refreshCycleId
});

msg._location_test = true;
msg._location_test_case = testCase;
msg.alarm_arrival_test = true;

msg.confirm_action = confirmAction;
msg.cancel_action = cancelAction;
msg.confirm_action_title = "Confirmar teste";
msg.cancel_action_title = "Cancelar teste";
msg.notification_title = "[TESTE] Confirmação do alarme";
msg.notification_tag = "alarm_arrival_confirmation_test";

if (source !== "manual") {
    msg.notification_message =
        "[TESTE] " +
        (labels[source] || source) +
        " está chegando (" +
        stage +
        "). Os triggers de localização chegaram ao fluxo do alarme. " +
        "Confirme para validar a ação da notificação. " +
        "Nenhum desarme será executado.";
} else {
    msg.notification_message =
        "Teste do fluxo de notificação acionável. " +
        "Nenhuma ação de desarme será executada.";
}

node.status({
    fill: "yellow",
    shape: "dot",
    text: `TESTE aguardando resposta: ${source}/${stage}`
});

return msg;

const REQUIRED = ["input_boolean.codex_alertas_iphone","input_boolean.codex_resumo_diario_iphone","input_number.codex_alerta_aviso_percentual","input_number.codex_alerta_critico_percentual","input_number.codex_alerta_cache_minimo","input_number.codex_alerta_saldo_creditos","sensor.codex_previsao_ate_o_reset","sensor.codex_limite_usado","sensor.codex_eficiencia_de_cache","sensor.codex_creditos_extras","sensor.codex_uso_projetado_no_reset","sensor.codex_folga_projetada_no_reset","sensor.codex_ritmo_do_limite","sensor.codex_limite_disponivel","sensor.codex_proximo_reset"];
const KEY = "codex_alertas_state_v1";
let state = flow.get(KEY, "persistent") || { values: {}, ready: false, sent: {} };
const event = msg.payload || {};

function num(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function build(title, message, kind) {
  const now = Date.now();
  const cooldownMs = kind === "critical" ? 60 * 60 * 1000 : 6 * 60 * 60 * 1000;
  if (now - Number(state.sent[kind] || 0) < cooldownMs) return null;
  state.sent[kind] = now;
  return { title, message, kind, at: new Date(now).toISOString() };
}

function summary() {
  if (state.values["input_boolean.codex_alertas_iphone"] !== "on"
      || state.values["input_boolean.codex_resumo_diario_iphone"] !== "on") return null;
  return build(
    "Codex — resumo diário",
    "Uso: " + (state.values["sensor.codex_limite_usado"] || "?") + "%; " +
      "projeção no reset: " + (state.values["sensor.codex_uso_projetado_no_reset"] || "?") + "%; " +
      "folga: " + (state.values["sensor.codex_folga_projetada_no_reset"] || "?") + "%; " +
      "cache: " + (state.values["sensor.codex_eficiencia_de_cache"] || "?") + "%; " +
      "previsão: " + (state.values["sensor.codex_previsao_ate_o_reset"] || "?") + ".",
    "daily",
  );
}

if (msg.topic === "codex.daily_summary") {
  const alert = state.ready ? summary() : null;
  flow.set(KEY, state, "persistent");
  return alert ? [ { alert }, { alert }, { alert }, { alert } ] : null;
}

if (event.type === "manual_test") {
  const alert = build(
    "Codex — teste de alertas",
    "✅ O Node-RED está conectado ao iPhone de Gabriel. Uso atual: " +
      (state.values["sensor.codex_limite_usado"] || "?") + "%; projeção no reset: " +
      (state.values["sensor.codex_uso_projetado_no_reset"] || "?") + "%.",
    "test",
  );
  flow.set(KEY, state, "persistent");
  return alert ? [ { alert }, { alert }, { alert }, { alert } ] : null;
}

const entity = event.entity_id;
if (!entity || !REQUIRED.includes(entity)) return null;
const previous = state.values[entity];
state.values[entity] = String(event.state ?? "");
if (!state.ready) {
  state.ready = REQUIRED.every((id) => Object.prototype.hasOwnProperty.call(state.values, id));
  flow.set(KEY, state, "persistent");
  node.status({ fill: state.ready ? "green" : "yellow", shape: "dot", text: state.ready ? "monitorando" : "sincronizando" });
  return null;
}

if (state.values["input_boolean.codex_alertas_iphone"] !== "on") {
  flow.set(KEY, state, "persistent");
  node.status({ fill: "grey", shape: "ring", text: "alertas desativados" });
  return null;
}

let alert = null;
if (entity === "sensor.codex_previsao_ate_o_reset") {
  if (["atenção", "não aguenta"].includes(event.state) && previous !== event.state) {
    const critical = event.state === "não aguenta";
    alert = build(
      critical ? "Codex — risco de esgotamento" : "Codex — pouca folga até o reset",
      (critical ? "🔴" : "⚠️") + " Ritmo atual: " +
        (state.values["sensor.codex_ritmo_do_limite"] || "?") + "%/dia. Uso projetado no reset: " +
        (state.values["sensor.codex_uso_projetado_no_reset"] || "?") + "%. Reset: " +
        (state.values["sensor.codex_proximo_reset"] || "?") + ".",
      critical ? "critical" : "forecast_warning",
    );
  } else if (event.state === "aguenta" && ["atenção", "não aguenta"].includes(previous)) {
    alert = build("Codex — autonomia recuperada", "✅ O ritmo voltou a ser sustentável até o reset. Folga projetada: " + (state.values["sensor.codex_folga_projetada_no_reset"] || "?") + "%.", "recovery");
  }
} else if (entity === "sensor.codex_limite_usado") {
  const used = num(event.state); const old = num(previous, -1);
  const warning = num(state.values["input_number.codex_alerta_aviso_percentual"], 70);
  const critical = num(state.values["input_number.codex_alerta_critico_percentual"], 90);
  if (used >= critical && old < critical) alert = build("Codex — limite crítico", "🚨 Uso chegou a " + used + "%. Restam " + (state.values["sensor.codex_limite_disponivel"] || "?") + "% até o reset.", "critical");
  else if (used >= warning && old < warning) alert = build("Codex — limite em atenção", "⚠️ Uso chegou a " + used + "%. Folga projetada no reset: " + (state.values["sensor.codex_folga_projetada_no_reset"] || "?") + "%.", "usage_warning");
} else if (entity === "sensor.codex_eficiencia_de_cache") {
  const value = num(event.state); const old = num(previous, 101); const minimum = num(state.values["input_number.codex_alerta_cache_minimo"], 60);
  if (value < minimum && old >= minimum) alert = build("Codex — eficiência de cache baixa", "⚠️ A eficiência caiu para " + value + "%. Limite configurado: " + minimum + "%.", "cache_low");
} else if (entity === "sensor.codex_creditos_extras") {
  const value = num(event.state); const old = num(previous, -1); const minimum = num(state.values["input_number.codex_alerta_saldo_creditos"], 10);
  if (value < minimum && old >= minimum) alert = build("Codex — créditos extras baixos", "⚠️ O saldo caiu para " + value + " créditos.", "credits_low");
}

flow.set(KEY, state, "persistent");
node.status({ fill: alert ? "red" : "green", shape: alert ? "ring" : "dot", text: alert ? "alerta: " + alert.kind : "monitorando" });
return alert ? [ { alert }, { alert }, { alert }, { alert } ] : null;
